set -euo pipefail

VERSION="v0.6.4"
REPO="piusalfred/gotools"
API_URL="https://api.github.com/repos/$REPO/releases/latest"

# Structured exit codes — let CI pipelines react intelligently to different
# failure modes instead of a flat `exit 1` everywhere. The user-facing table
# lives in usage(); keep it in sync when changing these values.
readonly E_GENERIC=1
readonly E_USAGE=2
readonly E_NETWORK=3
readonly E_LOCK=4
readonly E_TOOL_NOT_FOUND=5
readonly E_OFFLINE=6
# Reserved for the documented public contract.
# shellcheck disable=SC2034
readonly E_POLICY=7
readonly E_ENVIRONMENT=8

MANIFEST_FILE=".gotools.json"
DEFAULT_STRATEGY="split"
DEFAULT_DIR="tools"
DEFAULT_GO_VERSION="inherit"
DEFAULT_MODULE_PREFIX=""

# Minimum Go version for tool directives. Shared by _require_go and the
# doctor command's Go check — change in one place.
MIN_GO_VERSION="1.24"

# In-memory tool store. Each line is: name|source|package|version
# Populated by _manifest_parse() and mutated by _manifest_tool_set/remove.
# Flushed to .gotools.json by _manifest_flush().
_MANIFEST_TOOLS=""

# Dry-run mode — set by _parse_dry_run(). When true, destructive commands
# print what they would do but make no changes.
_DRY_RUN=false

# Offline mode — set via the --offline flag or GOTOOLS_OFFLINE=1. When true,
# commands refuse to do anything that would need the network: sync only takes
# the fingerprint fast path, install/upgrade refuse outright.
_OFFLINE=false

# Verbose mode — set via GOTOOLS_VERBOSE=1 env var or --verbose flag.
# When true, print every go command before executing it.
_VERBOSE="${GOTOOLS_VERBOSE:-0}"

# Trace mode — set via GOTOOLS_TRACE=1 env var.
# When true, log each tool execution as a JSON Lines record to
# .gotools_trace.log in the project root. Each record includes a
# "level" field: "info" (exit 0), "error" (tool ran but failed),
# or "fatal" (gotools itself errored before executing the tool).
_TRACE="${GOTOOLS_TRACE:-0}"

# Output format — set by _parse_output_format(). "text" unless a --format/
# --json/--text flag selects json. The helper resets it before scanning so
# repeated in-process calls (unit tests source the bundle) never leak state.
_OUTPUT_FORMAT="text"

# _PROJECT_ROOT — set by _find_project_root(). The directory containing
# .gotools.json, found by walking up from $PWD (like git finds .git).
# If not found, defaults to $PWD. Commands operate relative to this root.
_PROJECT_ROOT=""

# _find_project_root — walk up the directory tree looking for .gotools.json.
# If found, cd to that directory and set _PROJECT_ROOT. Otherwise, stay in $PWD.



_find_project_root() {
    local dir="$PWD"
    while [[ "$dir" != "/" ]]; do
        if [[ -f "$dir/$MANIFEST_FILE" ]]; then
            _PROJECT_ROOT="$dir"
            cd "$dir" 2>/dev/null || true
            return 0
        fi
        dir="$(dirname "$dir")"
    done
    # Check root directory too
    if [[ -f "/$MANIFEST_FILE" ]]; then
        _PROJECT_ROOT="/"
        cd "/" 2>/dev/null || true
        return 0
    fi
    _PROJECT_ROOT="$PWD"
    return 0
}

# Capture the original environment once at startup, before any load_config
# call sets these variables in the current shell. This is the only reliable
# way to distinguish "user passed GOTOOLS_DIR=x ./gotools ..." from
# "load_config already ran and set GOTOOLS_DIR earlier in this process".
_ORIG_ENV_STRATEGY="${GOTOOLS_STRATEGY:-}"
_ORIG_ENV_DIR="${GOTOOLS_DIR:-}"
_ORIG_ENV_GO_VERSION="${GOTOOLS_GO_VERSION:-}"
_ORIG_ENV_MODULE_PREFIX="${GOTOOLS_MODULE_PREFIX:-}"

_CONFIG_LOADED=false

# ---------------------------------------------------------------------------
# Config helpers
# ---------------------------------------------------------------------------

load_config() {
    if [[ "$_CONFIG_LOADED" == "true" ]]; then
        return
    fi

    # find project root by walking up from $PWD.
    _find_project_root

    # Drop stray temp files from a manifest write that crashed mid-flight.
    _manifest_flush_cleanup

    if [[ -f "$MANIFEST_FILE" ]]; then
        # Fail loudly on manifests written by a newer gotools.
        _manifest_check_version
        _manifest_parse "$MANIFEST_FILE"
    fi

    # Startup env overrides > config file > defaults.
    # Need to re-resolve after parsing because the manifest/env may have set these
    # to empty strings, and we need defaults to kick in for empty values.
    GOTOOLS_STRATEGY="${_ORIG_ENV_STRATEGY:-${GOTOOLS_STRATEGY:-$DEFAULT_STRATEGY}}"
    GOTOOLS_DIR="${_ORIG_ENV_DIR:-${GOTOOLS_DIR:-$DEFAULT_DIR}}"
    GOTOOLS_GO_VERSION="${_ORIG_ENV_GO_VERSION:-${GOTOOLS_GO_VERSION:-$DEFAULT_GO_VERSION}}"
    GOTOOLS_MODULE_PREFIX="${_ORIG_ENV_MODULE_PREFIX:-${GOTOOLS_MODULE_PREFIX:-$DEFAULT_MODULE_PREFIX}}"

    # Normalize: treat empty module_prefix as unset so auto-detection kicks in
    # in resolve_module_prefix.
    [[ -n "${GOTOOLS_MODULE_PREFIX:-}" ]] || GOTOOLS_MODULE_PREFIX=""

    _CONFIG_LOADED=true
}

reload_config() {
    _CONFIG_LOADED=false
    load_config
}

# _go_version_raw — print the bare go version string (e.g. "1.24.3"), empty
# if go is missing or `go env GOVERSION` fails. Non-fatal, never exits.
_go_version_raw() {
    command -v go >/dev/null 2>&1 || return 1
    go env GOVERSION 2>/dev/null | sed 's/^go//'
}

# _version_meets_min <actual> <required> — compare X.Y versions numerically.
#   rc 0: actual >= required
#   rc 1: actual < required
#   rc 2: undetectable (actual empty / no X.Y pair in either version)
# Pure: no output, no exit. Extracts the first [0-9]+\.[0-9]+ pair so inputs
# like "1.24.3", "go1.24", or "devel go1.26-abc123" all work.
_version_meets_min() {
    local actual="$1" required="$2"
    local amaj amin rmaj rmin
    [[ "$actual" =~ ([0-9]+)\.([0-9]+) ]] || return 2
    amaj="${BASH_REMATCH[1]}"
    amin="${BASH_REMATCH[2]}"
    [[ "$required" =~ ([0-9]+)\.([0-9]+) ]] || return 2
    rmaj="${BASH_REMATCH[1]}"
    rmin="${BASH_REMATCH[2]}"
    if (( amaj > rmaj )); then return 0; fi
    if (( amaj < rmaj )); then return 1; fi
    if (( amin >= rmin )); then return 0; fi
    return 1
}

# _require_go — verify Go is installed and >= 1.24 (minimum for tool directives).
_require_go() {
    if ! command -v go &>/dev/null; then
        echo "❌ Go is not installed. Please install Go 1.24 or higher." >&2
        echo "   https://go.dev/dl/" >&2
        exit $E_ENVIRONMENT
    fi
    local go_ver
    go_ver=$(_go_version_raw) || true
    if [[ -z "$go_ver" ]]; then
        echo "❌ Could not determine Go version." >&2
        exit $E_ENVIRONMENT
    fi
    if ! _version_meets_min "$go_ver" "$MIN_GO_VERSION"; then
        echo "❌ Go $go_ver is too old. Go 1.24 or higher is required." >&2
        exit $E_ENVIRONMENT
    fi
}

# ---- Lockfile (concurrent operation safety) -------------------------
_LOCK_FILE=""
_LOCK_HELD=false

# _acquire_lock — try to acquire the gotools lockfile. Reentrant: if this
# process already holds the lock, returns immediately.
_acquire_lock() {
    if $_LOCK_HELD; then return; fi
    local lock_dir="${GOTOOLS_DIR:-tools}"
    mkdir -p "$lock_dir"
    _LOCK_FILE="$lock_dir/.gotools.lock"
    local timeout=10 waited=0
    while ! mkdir "$_LOCK_FILE" 2>/dev/null; do
        if [[ $waited -ge $timeout ]]; then
            echo "❌ Another gotools process is running. Try again later." >&2
            exit $E_LOCK
        fi
        sleep 0.5
        waited=$((waited + 1))
    done
    _LOCK_HELD=true
    trap '_release_lock' EXIT
}

# _release_lock — remove the lockfile.
_release_lock() {
    if $_LOCK_HELD; then
        [[ -n "${_LOCK_FILE:-}" && -d "${_LOCK_FILE:-}" ]] && rmdir "$_LOCK_FILE" 2>/dev/null || true
        _LOCK_HELD=false
    fi
}

# _go — run a go command, printing it first if verbose mode is on.
# Usage: _go [args...]  (calls `go` with the same args)
_go() {
    if [[ "$_VERBOSE" == "1" || "$_VERBOSE" == "true" ]]; then
        echo "  ↳ go $*" >&2
    fi
    go "$@"
}

# _parse_dry_run — check remaining args for --dry-run, remove it, set _DRY_RUN.
# Call this at the top of destructive commands after load_config.
_parse_dry_run() {
    local filtered=()
    for arg in "$@"; do
        if [[ "$arg" == "--dry-run" ]]; then
            _DRY_RUN=true
        else
            filtered+=("$arg")
        fi
    done
    # Return filtered args via a global (bash can't return arrays).
    # ${filtered[@]+...} keeps the expansion legal when filtered is empty
    # under `set -u` on bash < 4.4.
    _PARSED_ARGS=(${filtered[@]+"${filtered[@]}"})
}

# relative_path <absolute_or_relative>
#   Prints the path relative to the current working directory.
#   Pure-bash implementation — no python3 or GNU realpath required.
relative_path() {
    local target="$1"

    # If already relative and doesn't need resolving, just clean it up.
    # Convert to absolute so the algorithm below always works.
    [[ "$target" != /* ]] && target="$PWD/$target"

    # Normalise both paths: resolve /./, remove trailing slashes,
    # collapse repeated slashes.  We avoid readlink/realpath so this
    # works on macOS and Linux without extra tools.
    local abs_target abs_base
    abs_target=$(cd "$(dirname "$target")" 2>/dev/null && echo "$PWD/$(basename "$target")") \
        || { echo "$1"; return; }
    abs_base="$PWD"

    # Split into arrays on '/'.
    local IFS='/'
    read -ra t_parts <<< "$abs_target"
    read -ra b_parts <<< "$abs_base"

    # Find the length of the common prefix.
    local i=0
    while [[ $i -lt ${#t_parts[@]} && $i -lt ${#b_parts[@]} && "${t_parts[$i]}" == "${b_parts[$i]}" ]]; do
        (( i++ ))
    done

    # Build the relative path: one ".." for each remaining base component,
    # then append the remaining target components.
    local rel=""
    local j
    for (( j=i; j<${#b_parts[@]}; j++ )); do
        rel="${rel}../"
    done
    for (( j=i; j<${#t_parts[@]}; j++ )); do
        rel="${rel}${t_parts[$j]}/"
    done

    # Strip trailing slash, default to "." for identical paths.
    rel="${rel%/}"
    echo "${rel:-.}"
}

# _parse_offline [args...] — set _OFFLINE from a --offline flag in the args
# or the GOTOOLS_OFFLINE=1 env var. Call at the top of commands that support
# offline mode. Always returns 0 (the env check must not trip set -e).
_parse_offline() {
    for arg in "$@"; do
        case "$arg" in --offline) _OFFLINE=true ;; esac
    done
    if [[ "${GOTOOLS_OFFLINE:-0}" == "1" ]]; then
        _OFFLINE=true
    fi
}

# _parse_output_format [args...] — scan args for output-format flags and set
# _OUTPUT_FORMAT. --format=json | --json → json; --format=text | --text →
# text. Any other --format=<x> → usage error. Always returns 0 otherwise
# (set -e safe). Resets to "text" first so repeated in-process calls never
# leak a previous call's format. Callers re-scan the args to reject any
# leftover positional junk.
_parse_output_format() {
    _OUTPUT_FORMAT="text"
    local arg
    for arg in "$@"; do
        case "$arg" in
            --json)        _OUTPUT_FORMAT="json" ;;
            --text)        _OUTPUT_FORMAT="text" ;;
            --format=json) _OUTPUT_FORMAT="json" ;;
            --format=text) _OUTPUT_FORMAT="text" ;;
            --format=*)
                echo "❌ Unknown output format: ${arg#--format=}" >&2
                echo "   Supported formats: json, text" >&2
                exit $E_USAGE
                ;;
        esac
    done
}

# _parallel_for <max-jobs> <fn> [args...]
#   Runs fn concurrently over argument groups delimited by "::", at most
#   max-jobs at a time, then waits for all. Each invocation's output is
#   line-prefixed with [<first group arg>] so interleaved output stays
#   readable. Portable to bash 3.2 (no `wait -n`): the oldest job is reaped
#   whenever the cap is reached. Returns the first non-zero job status.
_parallel_for() {
    local max_jobs="$1" fn="$2"
    shift 2
    # Separate declaration/assignment: bash 3.2 cannot initialize two
    # arrays in a single `local` statement.
    local -a group pids
    group=()
    pids=()
    local running=0 fail_status=0 label
    local arg
    for arg in "$@"; do
        if [[ "$arg" == "::" ]]; then
            label="${group[0]}"
            # The subshell wrapper is required: bash 3.2 returns from a
            # function immediately after backgrounding a pipeline under
            # `set -e` (the classic errexit/& bug).
            (
                "$fn" "${group[@]}" 2>&1 | while IFS= read -r line; do
                    echo "[$label] $line"
                done
            ) &
            pids+=($!)
            running=$((running + 1))
            group=()
            # Only reap once we EXCEED the cap: with max_jobs=1 the second
            # job must launch before the first is waited on, otherwise the
            # semaphore degenerates into serial execution.
            if [[ $running -gt $max_jobs ]]; then
                _parallel_reap
                # Drop the oldest pid. The explicit branch avoids expanding
                # an empty array under `set -u` on bash < 4.4.
                if [[ ${#pids[@]} -gt 1 ]]; then
                    pids=("${pids[@]:1}")
                else
                    pids=()
                fi
                running=$((running - 1))
            fi
        else
            group+=("$arg")
        fi
    done
    local pid
    # Safe expansion: pids may be empty when no job was left running.
    for pid in ${pids[@]+"${pids[@]}"}; do
        if wait "$pid"; then
            fail_status=$fail_status
        else
            _parallel_record_failure $?
        fi
    done
    [[ $fail_status -eq 0 ]] || return $fail_status
}

# _parallel_reap — wait for the oldest running job, recording its status.
# Uses pids[0] and fail_status from the caller's scope.
_parallel_reap() {
    if wait "${pids[0]}"; then
        return 0
    fi
    _parallel_record_failure $?
    return 0
}

# _parallel_record_failure <status> — remember the first non-zero job status.
_parallel_record_failure() {
    local status="$1"
    if [[ $status -ne 0 && $fail_status -eq 0 ]]; then
        fail_status=$status
    fi
}

# _sha256 <file> — print the SHA-256 hash of a file.
# Uses sha256sum (Linux) or shasum -a 256 (macOS); returns 1 if neither exists.
_sha256() {
    if command -v sha256sum &>/dev/null; then
        sha256sum "$1" | awk '{print $1}'
    elif command -v shasum &>/dev/null; then
        shasum -a 256 "$1" | awk '{print $1}'
    else
        return 1
    fi
}

# _json_escape — escape a string for inclusion in a JSON string value.
# Escapes: backslash, double-quote, and control characters (0x00-0x1f).
_json_escape() {
    local s="$1"
    local i c escaped=""
    for ((i = 0; i < ${#s}; i++)); do
        c="${s:i:1}"
        case "$c" in
            $'\\') escaped+='\\' ;;
            '"')   escaped+='\"'  ;;
            $'\n') escaped+='\n'  ;;
            $'\r') escaped+='\r'  ;;
            $'\t') escaped+='\t'  ;;
            *)     escaped+="$c"  ;;
        esac
    done
    printf '%s' "$escaped"
}

# Trace logging (opt-in via GOTOOLS_TRACE=1) — appends one JSON Lines
# record per tool invocation to .gotools_trace.log in the project root.
# Format:
#   {"ts":"<iso8601>","level":"<info|error>","tool":"<name>","binary":"<path>","cmd":"<reconstructed>","strategy":"<s>","stdin":"<pipe|terminal>","exit_code":<int>,"args":["...",...],"env":{...}}
# _trace_exec BINARY EXIT_CODE TOOL_NAME [ARGS...]
_trace_exec() {
    if [[ "$_TRACE" != "1" && "$_TRACE" != "true" ]]; then
        return
    fi
    local _bin="$1"
    local _exit_code="$2"
    local _tool="$3"
    shift 3

    local _ts _stdin _json_args="" _first=1 _arg _cmd _level
    _ts=$(date '+%Y-%m-%dT%H:%M:%S')
    _stdin=$([ -t 0 ] && echo "terminal" || echo "pipe")

    # Compute level from exit code.
    if [[ "$_exit_code" -eq 0 ]]; then
        _level="info"
    else
        _level="error"
    fi

    # Reconstruct the full gotools invocation — copy-pasteable for reproduction.
    _cmd="gotools exec $_tool"
    for _arg in "$@"; do
        if [[ "$_arg" =~ [[:space:]] ]]; then
            _cmd+=" \"$_arg\""
        else
            _cmd+=" $_arg"
        fi
    done

    for _arg in "$@"; do
        if [[ $_first -eq 1 ]]; then
            _json_args+="\"$(_json_escape "$_arg")\""
            _first=0
        else
            _json_args+=",\"$(_json_escape "$_arg")\""
        fi
    done

    printf '{"ts":"%s","level":"%s","tool":"%s","binary":"%s","cmd":"%s","strategy":"%s","stdin":"%s","exit_code":%d,"args":[%s],"env":{"GOTOOLS_STRATEGY":"%s","GOTOOLS_DIR":"%s","GOTOOLS_GO_VERSION":"%s","GOTOOLS_MODULE_PREFIX":"%s","GOTOOLS_VERBOSE":"%s","GOTOOLS_TRACE":"%s"}}\n' \
        "$_ts" \
        "$_level" \
        "$(_json_escape "$_tool")" \
        "$(_json_escape "$_bin")" \
        "$(_json_escape "$_cmd")" \
        "$(_json_escape "$GOTOOLS_STRATEGY")" \
        "$_stdin" \
        "$_exit_code" \
        "$_json_args" \
        "$(_json_escape "${GOTOOLS_STRATEGY:-}")" \
        "$(_json_escape "${GOTOOLS_DIR:-}")" \
        "$(_json_escape "$(resolve_go_version)")" \
        "$(_json_escape "$(resolve_module_prefix)")" \
        "$(_json_escape "${GOTOOLS_VERBOSE:-0}")" \
        "$(_json_escape "${GOTOOLS_TRACE:-0}")" \
        >> "$_PROJECT_ROOT/.gotools_trace.log"
}

# _trace_fatal — emit a "fatal" trace record when gotools itself errors
# out before a tool is executed (missing go.mod, unknown tool, etc.).
# _trace_fatal MESSAGE [TOOL_NAME]
_trace_fatal() {
    if [[ "$_TRACE" != "1" && "$_TRACE" != "true" ]]; then
        return
    fi
    local _message="$1"
    local _tool="${2:-unknown}"
    local _ts _stdin
    _ts=$(date '+%Y-%m-%dT%H:%M:%S')
    _stdin=$([ -t 0 ] && echo "terminal" || echo "pipe")
    printf '{"ts":"%s","level":"fatal","tool":"%s","error":"%s","strategy":"%s","stdin":"%s","env":{"GOTOOLS_STRATEGY":"%s","GOTOOLS_DIR":"%s","GOTOOLS_GO_VERSION":"%s","GOTOOLS_MODULE_PREFIX":"%s","GOTOOLS_VERBOSE":"%s","GOTOOLS_TRACE":"%s"}}\n' \
        "$_ts" \
        "$(_json_escape "$_tool")" \
        "$(_json_escape "$_message")" \
        "$(_json_escape "${GOTOOLS_STRATEGY:-}")" \
        "$_stdin" \
        "$(_json_escape "${GOTOOLS_STRATEGY:-}")" \
        "$(_json_escape "${GOTOOLS_DIR:-}")" \
        "$(_json_escape "$(resolve_go_version)")" \
        "$(_json_escape "$(resolve_module_prefix)")" \
        "$(_json_escape "${GOTOOLS_VERBOSE:-0}")" \
        "$(_json_escape "${GOTOOLS_TRACE:-0}")" \
        >> "$_PROJECT_ROOT/.gotools_trace.log"
}

# ---------------------------------------------------------------------------
# Manifest helpers (.gotools.json)
# ---------------------------------------------------------------------------

# _MANIFEST_SCHEMA_VERSION — the manifest schema this gotools understands.
# Bump ONLY when load_config would misinterpret a newer format. Additive
# changes (new optional key, new strategy value) do not require a bump.
readonly _MANIFEST_SCHEMA_VERSION=1

# _manifest_read_version [file] — echo the integer schema version (default 1).
# Shape-aware: the top-level version is unquoted JSON ("version": 1,) and
# lands in $3 as ": 1,"; a quoted value (e.g. a tool entry's "version":
# "v0.8.0") lands in $4. Pre-version manifests and non-numeric matches
# (the "version" key of a tool entry) default to v1.
_manifest_read_version() {
    local mf="${1:-$MANIFEST_FILE}"
    local version
    version=$(awk -F'"' '/"version":/ { if (NF >= 4) print $4; else print $3; exit }' "$mf")
    version="${version#: }"
    version="${version%,}"
    [[ "$version" =~ ^[0-9]+$ ]] || version=1
    echo "$version"
}

# _manifest_validate [file] — non-fatal structural validation for read-only
# diagnostics (the doctor command). rc 0 valid; 1 missing file; 2 written by
# a newer gotools (prints the same 3-line message _manifest_check_version
# prints, but returns instead of exiting); 3 unparseable (no top-level
# "strategy" key, or the last non-blank line is not "}" — truncated JSON).
_manifest_validate() {
    local mf="${1:-$MANIFEST_FILE}"
    [[ -f "$mf" ]] || return 1
    local version
    version=$(_manifest_read_version "$mf")
    if [[ "$version" -gt "$_MANIFEST_SCHEMA_VERSION" ]]; then
        echo "❌ This project's $MANIFEST_FILE requires schema version ${version}." >&2
        echo "   Your gotools (${VERSION}) only understands version ${_MANIFEST_SCHEMA_VERSION}." >&2
        echo "   Upgrade: https://github.com/$REPO/releases" >&2
        return 2
    fi
    local strategy last
    strategy=$(awk -F'"' '/"strategy":/ {print $4; exit}' "$mf")
    last=$(awk 'NF { line=$0 } END { print line }' "$mf")
    if [[ -z "$strategy" || "$last" != "}" ]]; then
        echo "❌ $MANIFEST_FILE is not parseable: truncated or malformed JSON." >&2
        return 3
    fi
    return 0
}

# _manifest_check_version — refuse manifests written by a NEWER gotools so
# old versions fail loudly instead of silently misparsing. Pre-version
# manifests (no top-level "version" key) default to v1. A non-numeric match
# means the "version" key belongs to a tool entry, not the top level.
_manifest_check_version() {
    local version
    version=$(_manifest_read_version "$MANIFEST_FILE")
    if [[ "$version" -gt "$_MANIFEST_SCHEMA_VERSION" ]]; then
        echo "❌ This project's $MANIFEST_FILE requires schema version ${version}." >&2
        echo "   Your gotools (${VERSION}) only understands version ${_MANIFEST_SCHEMA_VERSION}." >&2
        echo "   Upgrade: https://github.com/$REPO/releases" >&2
        exit $E_ENVIRONMENT
    fi
}

# _manifest_parse — read .gotools.json into config vars and _MANIFEST_TOOLS.
# Uses awk on the known, fixed JSON schema (no jq/python3 dependency).



_manifest_parse() {
    local mf="$1"
    [[ -f "$mf" ]] || return 1

    # Parse top-level string fields
    GOTOOLS_STRATEGY=$(awk -F'"' '/"strategy":/  {print $4; exit}' "$mf")
    GOTOOLS_DIR=$(awk -F'"'     '/"dir":/       {print $4; exit}' "$mf")
    GOTOOLS_GO_VERSION=$(awk -F'"' '/"go_version":/ {print $4; exit}' "$mf")
    GOTOOLS_MODULE_PREFIX=$(awk -F'"' '/"module_prefix":/ {print $4; exit}' "$mf")

    # Parse tools section. We match lines that look like tool entries:
    #     "name": {
    #       "source": "go",
    #       "package": "pkg",
    #       "version": "ver"
    #     }
    _MANIFEST_TOOLS=""
    local in_tools=false _tname="" _tsource="" _tpkg="" _tver=""
    while IFS= read -r line; do
        # Detect start/end of "tools" object
        if [[ "$line" =~ ^[[:space:]]*\"tools\"[[:space:]]*:[[:space:]]*\{ ]]; then
            in_tools=true
            continue
        fi
        if $in_tools && [[ "$line" =~ ^[[:space:]]*\} ]]; then
            # Could be closing a tool or closing the tools object
            if [[ -n "$_tname" ]]; then
                _MANIFEST_TOOLS+="${_tname}|${_tsource}|${_tpkg}|${_tver}"$'\n'
                _tname=""; _tsource=""; _tpkg=""; _tver=""
            fi
            # If next non-blank line would be the top-level closing, we're done
            continue
        fi
        if ! $in_tools; then continue; fi

        # Match tool name key:     "name": {
        if [[ "$line" =~ ^[[:space:]]*\"([^\"]+)\"[[:space:]]*:[[:space:]]*\{ ]]; then
            _tname="${BASH_REMATCH[1]}"
            _tsource=""; _tpkg=""; _tver=""
            continue
        fi
        # Match fields inside a tool entry
        if [[ -n "$_tname" ]]; then
            if [[ "$line" =~ \"source\":[[:space:]]*\"([^\"]+)\" ]]; then
                _tsource="${BASH_REMATCH[1]}"
            elif [[ "$line" =~ \"package\":[[:space:]]*\"([^\"]+)\" ]]; then
                _tpkg="${BASH_REMATCH[1]}"
            elif [[ "$line" =~ \"version\":[[:space:]]*\"([^\"]+)\" ]]; then
                _tver="${BASH_REMATCH[1]}"
            elif [[ "$line" =~ ^[[:space:]]*\} ]]; then
                # End of this tool entry
                _MANIFEST_TOOLS+="${_tname}|${_tsource}|${_tpkg}|${_tver}"$'\n'
                _tname=""; _tsource=""; _tpkg=""; _tver=""
            fi
        fi
    done < "$mf"
}

# _manifest_flush — write config vars and _MANIFEST_TOOLS back to .gotools.json.
_manifest_flush() {
    local mf="${1:-$MANIFEST_FILE}"
    local strategy="${GOTOOLS_STRATEGY:-$DEFAULT_STRATEGY}"
    local dir="${GOTOOLS_DIR:-$DEFAULT_DIR}"
    local go_ver="${GOTOOLS_GO_VERSION:-$DEFAULT_GO_VERSION}"

    # Resolve the module prefix at flush time so the manifest never stores
    # an empty string. Falls back to the tools directory itself if there
    # is no parent go.mod and no explicit prefix configured.
    local prefix
    prefix=$(resolve_module_prefix)
    if [[ -z "$prefix" ]]; then
        prefix="$dir"
    fi

    # Build tools JSON block
    local tools_json=""
    # Deterministic order in the committed manifest: source, then package,
    # then version, then name (final tiebreak for aliases) — so diffs are
    # easy to read when tools are added or removed.
    local tools_sorted
    tools_sorted=$(printf '%s\n' "$_MANIFEST_TOOLS" | LC_ALL=C sort -t'|' -k2,2 -k3,3 -k4,4 -k1,1)

    local first=true
    local _n _s _p _v
    while IFS='|' read -r _n _s _p _v; do
        [[ -z "$_n" ]] && continue
        if $first; then first=false; else tools_json+=","$'\n'; fi
        tools_json+="    \"${_n}\": {"$'\n'
        tools_json+="      \"source\": \"${_s}\","$'\n'
        tools_json+="      \"package\": \"${_p}\","$'\n'
        tools_json+="      \"version\": \"${_v}\""$'\n'
        tools_json+="    }"
    done <<< "$tools_sorted"

    # Atomic write: build in a temp file, then rename over the target.
    # A crash mid-write leaves the previous manifest intact; the stray
    # temp file is removed by _manifest_flush_cleanup on the next run.
    # The PID suffix keeps concurrent writes from colliding even if the
    # lock was bypassed.
    local tmpfile="${mf}.tmp.$$"
    cat > "$tmpfile" <<MANIFEST_EOF
{
  "version": 1,
  "strategy": "${strategy}",
  "dir": "${dir}",
  "go_version": "${go_ver}",
  "module_prefix": "${prefix}",
  "tools": {
${tools_json}
  }
}
MANIFEST_EOF
    mv "$tmpfile" "$mf"
}

# _manifest_flush_cleanup — remove temp files left behind by a crash during
# an atomic manifest write. They are never valid across invocations.
_manifest_flush_cleanup() {
    rm -f "${MANIFEST_FILE}.tmp."* 2>/dev/null || true
}

# _manifest_tools_list — echo tool names, one per line.
_manifest_tools_list() {
    local _n
    while IFS='|' read -r _n _ _ _; do
        [[ -n "$_n" ]] && echo "$_n"
    done <<< "$_MANIFEST_TOOLS"
}

# _manifest_tool_entry — echo "source|package|version" for a tool name.
_manifest_tool_entry() {
    local want="$1" _n _s _p _v
    while IFS='|' read -r _n _s _p _v; do
        if [[ "$_n" == "$want" ]]; then
            echo "${_s}|${_p}|${_v}"
            return 0
        fi
    done <<< "$_MANIFEST_TOOLS"
    return 1
}

# _manifest_tool_exists — check if a tool name is in the manifest.
_manifest_tool_exists() {
    _manifest_tool_entry "$1" >/dev/null 2>&1
}

# _manifest_tool_set — add or update a tool entry in memory (does NOT flush).
_manifest_tool_set() {
    local name="$1" source="$2" pkg="$3" ver="$4"
    local new_tools="" found=false
    while IFS='|' read -r n s p v; do
        [[ -z "$n" ]] && continue
        if [[ "$n" == "$name" ]]; then
            new_tools+="${name}|${source}|${pkg}|${ver}"$'\n'
            found=true
        else
            new_tools+="${n}|${s}|${p}|${v}"$'\n'
        fi
    done <<< "$_MANIFEST_TOOLS"
    if ! $found; then
        new_tools+="${name}|${source}|${pkg}|${ver}"$'\n'
    fi
    _MANIFEST_TOOLS="$new_tools"
}

# _manifest_tool_remove — remove a tool from memory (does NOT flush).
_manifest_tool_remove() {
    local name="$1"
    local new_tools=""
    while IFS='|' read -r n s p v; do
        [[ -z "$n" ]] && continue
        [[ "$n" != "$name" ]] && new_tools+="${n}|${s}|${p}|${v}"$'\n'
    done <<< "$_MANIFEST_TOOLS"
    _MANIFEST_TOOLS="$new_tools"
}

# _manifest_config_get — extract a single config value from the manifest file.
_manifest_config_get() {
    local key="$1" mf="${2:-$MANIFEST_FILE}"
    case "$key" in
        GOTOOLS_STRATEGY)     awk -F'"' '/"strategy":/  {print $4; exit}' "$mf" ;;
        GOTOOLS_DIR)          awk -F'"' '/"dir":/       {print $4; exit}' "$mf" ;;
        GOTOOLS_GO_VERSION)   awk -F'"' '/"go_version":/{print $4; exit}' "$mf" ;;
        GOTOOLS_MODULE_PREFIX) awk -F'"' '/"module_prefix":/{print $4; exit}' "$mf" ;;
        *) echo "❌ Unknown config key: $key" >&2; return 1 ;;
    esac
}

# _manifest_config_set — update a config field in the manifest file.
_manifest_config_set() {
    local key="$1" value="$2"
    case "$key" in
        GOTOOLS_STRATEGY)     GOTOOLS_STRATEGY="$value"     ;;
        GOTOOLS_DIR)          GOTOOLS_DIR="$value"          ;;
        GOTOOLS_GO_VERSION)   GOTOOLS_GO_VERSION="$value"    ;;
        GOTOOLS_MODULE_PREFIX) GOTOOLS_MODULE_PREFIX="$value" ;;
        *) echo "❌ Unknown config key: $key" >&2; return 1 ;;
    esac
    _manifest_flush
}

# _resolve_installed_version — after go get -tool, read back the version from the
# modfile's require block for the given package.



_resolve_installed_version() {
    local modfile="$1" pkg="$2"
    extract_version_for_pkg "$modfile" "$pkg"
}

# ---------------------------------------------------------------------------
# Parsing helpers for go.mod files
#
# extract_go_version_from_mod <modfile>
#   Prints the Go version from the `go` directive in a go.mod file.
extract_go_version_from_mod() {
    local modfile="$1"
    awk '$1 == "go" { print $2; exit }' "$modfile"
}
# ---------------------------------------------------------------------------

# extract_tools_from_mod <modfile>
#   Prints one package path per line from `tool` directives.
#   Handles both:
#     tool pkg
#     tool (
#       pkg1
#       pkg2
#     )
extract_tools_from_mod() {
    local modfile="$1"
    awk '
        /^tool[[:space:]]+\(/ { in_block=1; next }
        in_block && /^\)/ { in_block=0; next }
        in_block {
            gsub(/^[[:space:]]+/, "")
            gsub(/[[:space:]]+$/, "")
            if ($0 != "") print $0
            next
        }
        $1 == "tool" && $2 != "(" { print $2 }
    ' "$modfile"
}

# extract_version_for_pkg <modfile> <pkg>
#   Prints the version string for <pkg> from the require block(s) of <modfile>.
#   Handles subpackage paths like github.com/foo/bar/v2/cmd/baz by trying
#   progressively shorter prefixes until it finds a match in require.
extract_version_for_pkg() {
    local modfile="$1" pkg="$2"
    local candidate="$pkg"
    while [[ -n "$candidate" ]]; do
        local ver
        ver=$(awk -v p="$candidate" '
            /^require[[:space:]]+\(/ { in_req=1; next }
            in_req && /^\)/ { in_req=0; next }
            in_req {
                gsub(/^[[:space:]]+/, "")
                if ($1 == p) { gsub(/\/\/.*/, "", $2); print $2 }
                next
            }
            $1 == "require" && $2 == p { gsub(/\/\/.*/, "", $3); print $3 }
        ' "$modfile")
        if [[ -n "$ver" ]]; then
            echo "$ver"
            return
        fi
        # Strip the last path component and try again.
        local parent="${candidate%/*}"
        [[ "$parent" == "$candidate" ]] && break
        candidate="$parent"
    done
}

# extract_module_for_pkg <modfile> <pkg>
#   Prints the module root (require path) that provides <pkg>, by walking
#   progressively shorter path prefixes over the require block(s) — the same
#   algorithm as extract_version_for_pkg, but returning the module path.
#   E.g. honnef.co/go/tools/cmd/staticcheck → honnef.co/go/tools.
extract_module_for_pkg() {
    local modfile="$1" pkg="$2"
    local candidate="$pkg"
    while [[ -n "$candidate" ]]; do
        local mod
        mod=$(awk -v p="$candidate" '
            /^require[[:space:]]+\(/ { in_req=1; next }
            in_req && /^\)/ { in_req=0; next }
            in_req {
                gsub(/^[[:space:]]+/, "")
                if ($1 == p) { print $1 }
                next
            }
            $1 == "require" && $2 == p { print $2 }
        ' "$modfile")
        if [[ -n "$mod" ]]; then
            echo "$mod"
            return
        fi
        # Strip the last path component and try again.
        local parent="${candidate%/*}"
        [[ "$parent" == "$candidate" ]] && break
        candidate="$parent"
    done
}

# extract_pkg_from_mod <modfile>
#   Returns the FIRST tool package from a go.mod (convenience for single-tool mods).
extract_pkg_from_mod() {
    extract_tools_from_mod "$1" | head -n1
}

# strip_tools_from_mod <modfile>
#   Prints the file with all `tool` directives removed. Handles both forms:
#     tool pkg
#     tool (
#       pkg1
#       pkg2
#     )
#   Every other line (module, go, require blocks, replace, exclude, comments,
#   blank lines) is passed through verbatim. The caller owns writing the
#   output back (atomically — temp file + mv, like _manifest_flush).
strip_tools_from_mod() {
    local modfile="$1"
    awk '
        /^tool[[:space:]]+\(/ { in_block=1; next }
        in_block && /^\)/ { in_block=0; next }
        in_block { next }
        $1 == "tool" { next }
        { print }
    ' "$modfile"
}

# _gomod_tool_scan <modfile>
#   Prints one line per tool directive:  name pkg@version
#   Versions are resolved from the require blocks; a missing pin falls back
#   to @latest (same policy as extract_tools_with_versions).
_gomod_tool_scan() {
    local modfile="$1"
    while IFS= read -r pkg; do
        [[ -z "$pkg" ]] && continue
        local name ver
        name=$(infer_binary_name_from_pkg "$pkg")
        ver=$(extract_version_for_pkg "$modfile" "$pkg")
        echo "$name ${pkg}@${ver:-latest}"
    done < <(extract_tools_from_mod "$modfile")
}

# infer_binary_name_from_pkg <package-path>
#   Converts a Go package path (without @version) into the expected binary name.
#   Examples:
#     github.com/goreleaser/goreleaser/v2           -> goreleaser
#     github.com/goreleaser/goreleaser/v2/cmd/goreleaser -> goreleaser
#     golang.org/x/tools/cmd/goimports              -> goimports
#     honnef.co/go/tools/cmd/staticcheck            -> staticcheck
infer_binary_name_from_pkg() {
    local pkg="$1"
    # Remove version suffix: /v2, /v3, /v10, etc.
    pkg="${pkg%/v[0-9]*}"
    # If it ends with /cmd/<name>, take <name>
    if [[ "$pkg" =~ /cmd/([^/]+)$ ]]; then
        echo "${BASH_REMATCH[1]}"
        return
    fi
    # Fallback to basename
    basename "$pkg"
}

# resolve_binary_name <tool_name> <modfile>
#   Dereferences a tool alias to the actual Go binary name.
#   Reads the tool directive from the modfile and returns the inferred binary name.
#   Falls back to the tool_name itself if no directive is found.
resolve_binary_name() {
    local tool_name="$1" modfile="$2"
    local pkg
    pkg=$(extract_pkg_from_mod "$modfile")
    if [[ -n "$pkg" ]]; then
        infer_binary_name_from_pkg "$pkg"
    else
        echo "$tool_name"
    fi
}

# detect_strategy <dir>
#   Inspects the tools directory on disk and returns which strategy it
#   actually matches: unified, split, module, or empty (unknown).
#   If hybrid structures are detected (e.g., unified go.mod + split .mod files),
#   the dominant strategy is returned and a warning is printed to stderr.



detect_strategy() {
    local dir="${1:-$GOTOOLS_DIR}"
    [[ -d "$dir" ]] || return 0

    local has_unified=false has_module=false has_split=false

    # Check for unified: single go.mod at the tools root with tool directives
    if [[ -f "$dir/go.mod" ]] && grep -q '^tool ' "$dir/go.mod" 2>/dev/null; then
        has_unified=true
    fi

    # Check for module: subdirectories each containing go.mod
    for d in "$dir"/*/; do
        if [[ -d "$d" && -f "$d/go.mod" ]]; then
            has_module=true
            break
        fi
    done

    # Check for split: flat *.mod files (not go.mod)
    for f in "$dir"/*.mod; do
        if [[ -f "$f" && "$(basename "$f")" != "go.mod" ]]; then
            has_split=true
            break
        fi
    done

    # Count how many strategies are detected.
    local count=0
    $has_unified && count=$((count + 1))
    $has_module   && count=$((count + 1))
    $has_split    && count=$((count + 1))

    if [[ $count -gt 1 ]]; then
        echo "⚠️  Hybrid tools directory detected in $dir/:" >&2
        $has_unified && echo "   - unified  (go.mod with tool directives)" >&2
        $has_module   && echo "   - module   (subdirectories with go.mod)" >&2
        $has_split    && echo "   - split    (flat .mod files)" >&2
        echo "   Run 'gotools.sh migrate <strategy>' to clean up." >&2
    fi

    # Return the detected strategy using the original priority order.
    $has_unified && { echo "unified"; return; }
    $has_module   && { echo "module";   return; }
    $has_split    && { echo "split";    return; }
    # Empty / unknown
    return 0
}

resolve_go_version() {
    if [[ "$GOTOOLS_GO_VERSION" != "inherit" ]]; then
        echo "$GOTOOLS_GO_VERSION"
        return
    fi
    # Try the project root go.mod first.
    local root_mod="go.mod"
    if [[ -f "$root_mod" ]]; then
        local v
        v=$(awk '$1 == "go" { print $2; exit }' "$root_mod")
        if [[ -n "$v" ]]; then
            echo "$v"
            return
        fi
    fi
    # Fallback: ask the go tool itself.
    go env GOVERSION | sed 's/^go//' | awk -F. '{ print $1"."$2 }'
}

# resolve_module_prefix
#   Returns the module prefix to use for tool go.mod files.
#   Priority:
#     1. GOTOOLS_MODULE_PREFIX from .gotools.json (if non-empty)
#     2. Parent module path from root go.mod (e.g. github.com/user/repo)
#     3. Empty string — falls back to bare "tools" / "tools/<name>"
resolve_module_prefix() {
    # Explicit override takes priority.
    if [[ -n "${GOTOOLS_MODULE_PREFIX:-}" ]]; then
        echo "$GOTOOLS_MODULE_PREFIX"
        return
    fi
    # Auto-detect from root go.mod.
    local root_mod="go.mod"
    if [[ -f "$root_mod" ]]; then
        local mod
        mod=$(awk '$1 == "module" { print $2; exit }' "$root_mod")
        if [[ -n "$mod" ]]; then
            echo "$mod"
            return
        fi
    fi
    # No parent module found.
    echo ""
}

# tool_module_path [tool_name]
#   Builds the full module path for a tool go.mod using $GOTOOLS_DIR.
#   No args:  module path for the tools dir itself (unified strategy).
#   One arg:  module path for a specific tool.
#
#   Examples (GOTOOLS_DIR=tools, parent=github.com/user/repo):
#     tool_module_path              -> "github.com/user/repo/tools"
#     tool_module_path mockgen      -> "github.com/user/repo/tools/mockgen"
#
#   Examples (GOTOOLS_DIR=build/tools, parent=github.com/user/repo):
#     tool_module_path              -> "github.com/user/repo/build/tools"
#     tool_module_path mockgen      -> "github.com/user/repo/build/tools/mockgen"
#
#   Examples (GOTOOLS_DIR=tools, no parent go.mod):
#     tool_module_path              -> "tools"
#     tool_module_path mockgen      -> "tools/mockgen"
tool_module_path() {
    local prefix
    prefix=$(resolve_module_prefix)
    local dir_path="$GOTOOLS_DIR"
    if [[ $# -ge 1 && -n "$1" ]]; then
        dir_path="${dir_path}/${1}"
    fi
    if [[ -n "$prefix" ]]; then
        echo "${prefix}/${dir_path}"
    else
        echo "$dir_path"
    fi
}

# pkg_for_tool <tool-name>
#   Prints the full package path (e.g., github.com/.../cmd/tool) for the given tool name,
#   based on the current strategy. Returns 1 if not found.
pkg_for_tool() {
    local tool_name="$1"
    case "$GOTOOLS_STRATEGY" in
        unified)
            local modfile="$GOTOOLS_DIR/go.mod"
            [[ -f "$modfile" ]] || return 1
            while IFS= read -r pkg; do
                if [[ "$(infer_binary_name_from_pkg "$pkg")" == "$tool_name" ]]; then
                    echo "$pkg"
                    return 0
                fi
            done < <(extract_tools_from_mod "$modfile")
            ;;
        split)
            local modfile="$GOTOOLS_DIR/${tool_name}.mod"
            [[ -f "$modfile" ]] || return 1
            extract_pkg_from_mod "$modfile"
            ;;
        module)
            local modfile="$GOTOOLS_DIR/${tool_name}/go.mod"
            [[ -f "$modfile" ]] || return 1
            extract_pkg_from_mod "$modfile"
            ;;
    esac
    return 1
}

# tool_runnable <tool-name>
#   Probes whether `go tool <binary>` can run the tool under the current
#   strategy, mirroring the invocation forms cmd_exec uses. Prints a one-line
#   reason to stdout when NOT runnable. rc 0 runnable, 1 not runnable.
#
#   "Not runnable" means a GO-level failure: go missing, modfile missing, or
#   stderr matching a go error (^go( tool)?:, "no such tool", "is not a
#   tool", "no go.mod file found"). A tool that starts and then exits
#   non-zero on empty stdin (its own usage error, e.g. staticcheck) IS
#   runnable — the go toolchain found and launched it.
#
#   Read-only: stdin is /dev/null, GOTOOLCHAIN=local always (no toolchain
#   auto-download), plus GOPROXY=off in offline mode so a not-yet-downloaded
#   tool fails fast instead of touching the network.
tool_runnable() {
    local tool_name="$1"
    command -v go >/dev/null 2>&1 || { echo "go not installed"; return 1; }
    local modfile binary out rc=0
    case "$GOTOOLS_STRATEGY" in
        unified)
            modfile="$GOTOOLS_DIR/go.mod"
            [[ -f "$modfile" ]] || { echo "missing $modfile"; return 1; }
            binary=$(resolve_binary_name "$tool_name" "$modfile")
            # GOTOOLCHAIN=local: never auto-download a toolchain during
            # diagnostics. GOPROXY=off in offline mode: fail fast instead of
            # touching the network. Exported inside the subshell — bash 3.2
            # cannot apply array-expanded "VAR=val" words before a function
            # call ("command not found").
            out=$( (export GOTOOLCHAIN=local; $_OFFLINE && export GOPROXY=off; cd "$GOTOOLS_DIR" && _go tool "$binary" </dev/null) 2>&1 ) || rc=$?
            ;;
        split)
            modfile="$GOTOOLS_DIR/${tool_name}.mod"
            [[ -f "$modfile" ]] || { echo "missing $modfile"; return 1; }
            binary=$(resolve_binary_name "$tool_name" "$modfile")
            out=$( (export GOTOOLCHAIN=local; $_OFFLINE && export GOPROXY=off; _go tool -modfile="$modfile" "$binary" </dev/null) 2>&1 ) || rc=$?
            ;;
        module)
            modfile="$GOTOOLS_DIR/$tool_name/go.mod"
            [[ -f "$modfile" ]] || { echo "missing $modfile"; return 1; }
            binary=$(resolve_binary_name "$tool_name" "$modfile")
            out=$( (export GOTOOLCHAIN=local; $_OFFLINE && export GOPROXY=off; cd "$GOTOOLS_DIR/$tool_name" && _go tool "$binary" </dev/null) 2>&1 ) || rc=$?
            ;;
        *)
            echo "unknown strategy: $GOTOOLS_STRATEGY"
            return 1
            ;;
    esac
    [[ $rc -eq 0 ]] && return 0
    # Non-zero: only a go-level failure makes it NOT runnable. The verbosity
    # echo ("↳ go ...") goes to stderr first; it never matches this pattern.
    local reason
    reason=$(grep -E '^go( tool)?:|no such tool|is not a tool|no go\.mod file found' <<< "$out" | head -n1 || true)
    if [[ -n "$reason" ]]; then
        echo "$reason"
        return 1
    fi
    return 0
}

# ---------------------------------------------------------------------------
# extract_tools_with_versions
#   Outputs lines of: name pkg@version
#   Strategy-aware.
# ---------------------------------------------------------------------------
extract_tools_with_versions() {
    case "$GOTOOLS_STRATEGY" in
        unified)
            local modfile="$GOTOOLS_DIR/go.mod"
            [[ -f "$modfile" ]] || return 0
            while IFS= read -r pkg; do
                [[ -z "$pkg" ]] && continue
                local name ver
                name=$(infer_binary_name_from_pkg "$pkg")
                ver=$(extract_version_for_pkg "$modfile" "$pkg")
                if [[ -n "$ver" ]]; then
                    echo "$name ${pkg}@${ver}"
                else
                    echo "$name ${pkg}@latest"
                fi
            done < <(extract_tools_from_mod "$modfile")
            ;;

        split)
            for f in "$GOTOOLS_DIR"/*.mod; do
                [[ -f "$f" ]] || continue
                local name pkg ver
                name=$(basename "$f" .mod)
                pkg=$(extract_pkg_from_mod "$f")
                [[ -z "$pkg" ]] && continue
                ver=$(extract_version_for_pkg "$f" "$pkg")
                if [[ -n "$ver" ]]; then
                    echo "$name ${pkg}@${ver}"
                else
                    echo "$name ${pkg}@latest"
                fi
            done
            ;;

        module)
            for d in "$GOTOOLS_DIR"/*/; do
                [[ -d "$d" ]] || continue
                local modfile="$d/go.mod"
                [[ -f "$modfile" ]] || continue
                local name pkg ver
                name=$(basename "$d")
                pkg=$(extract_pkg_from_mod "$modfile")
                [[ -z "$pkg" ]] && continue
                ver=$(extract_version_for_pkg "$modfile" "$pkg")
                if [[ -n "$ver" ]]; then
                    echo "$name ${pkg}@${ver}"
                else
                    echo "$name ${pkg}@latest"
                fi
            done
            ;;

        *)
            echo "❌ Unknown strategy: $GOTOOLS_STRATEGY" >&2
            return 1
            ;;
    esac
}

# _cmd_help <command> — print per-command help.



_cmd_help() {
    local cmd="$1"
    case "$cmd" in
        init)
            echo "Usage: gotools.sh init [flags]"
            echo ""
            echo "  Bootstrap the project with a .gotools.json manifest."
            echo "  If the root go.mod declares tools via 'go get -tool', they are"
            echo "  adopted automatically (installed into gotools, directives stripped,"
            echo "  go.mod tidied) — unless --no-migrate is given."
            echo ""
            echo "  Flags:"
            echo "    --strategy=unified|split|module   Isolation strategy (default: split)"
            echo "    --dir=<path>                      Tools directory (default: tools)"
            echo "    --go=<version|inherit>            Go version for tools (default: inherit)"
            echo "    --prefix=<module-path>            Module prefix (default: auto from go.mod)"
            echo "    --no-migrate                      Leave the root go.mod untouched"
            echo "    --dry-run                         Print the plan without writing anything"
            echo ""
            echo "  Examples:"
            echo "    gotools.sh init"
            echo "    gotools.sh init --strategy=module --dir=.tools"
            echo "    gotools.sh init --go=1.24 --prefix=github.com/me/repo"
            ;;
        install)
            echo "Usage: gotools.sh install [name] <package@version> [--force]"
            echo ""
            echo "  Install a Go tool via 'go get -tool'. If only a package is given,"
            echo "  the tool name is inferred from the package path."
            echo ""
            echo "  Tool aliases: You can give the tool a custom name (alias). The"
            echo "  alias is used in gotools.sh (list, info, remove, exec, upgrade)"
            echo "  but the underlying Go binary name stays the same."
            echo ""
            echo "  Examples:"
            echo "    gotools.sh install golang.org/x/tools/cmd/goimports@latest"
            echo "    gotools.sh install mylint golang.org/x/tools/cmd/goimports@v0.38.0"
            echo "    gotools.sh exec mylint -w .   # runs goimports binary"
            echo ""
            echo "  Pipe mode — feed 'go install' commands via stdin:"
            echo "    echo 'go install pkg@latest' | gotools.sh       # pipe"
            echo "    gotools.sh <<< 'go install pkg@latest'          # herestring"
            echo "    gotools.sh <<EOF                               # heredoc"
            echo "    go install pkg1@v1"
            echo "    go install pkg2@v2"
            echo "    EOF"
            echo "    gotools.sh < tools.txt                         # file redirect"
            echo "    # The 'go install' prefix is optional — bare pkg@version works too"
            echo ""
            echo "  Options:"
            echo "    --force    Overwrite an existing tool with the same name"
            echo "    --offline  Refuse to install (needs the network), exit 6"
            ;;
        sync)
            echo "Usage: gotools.sh sync [--dry-run]"
            echo ""
            echo "  Sync tool state to match .gotools.json. Tidies existing modfiles"
            echo "  and reinstalls any tools from the manifest that are missing on disk"
            echo "  or whose installed version drifted from the manifest."
            echo ""
            echo "  If the on-disk strategy doesn't match the manifest, auto-migrates."
            echo ""
            echo "  Fast path: when nothing changed, a state fingerprint in"
            echo "  \$GOTOOLS_DIR/.gotools.fingerprint skips the reconciliation"
            echo "  entirely. Commit that file so fresh clones are fast too."
            echo ""
            echo "  Options:"
            echo "    --dry-run   Show what would be done without making changes"
            echo "    --offline   Hermetic: fingerprint match only, exit 6 otherwise"
            echo "                (GOTOOLS_OFFLINE=1 does the same)"
            echo "    --jobs N    Reinstall tools N at a time (default: 1, serial)."
            echo "                Parallel needs split/module; unified stays serial."
            echo "                GOTOOLS_JOBS=N does the same."
            ;;
        exec)
            echo "Usage: gotools.sh exec <tool-name> [args...]"
            echo ""
            echo "  Run a managed tool with the given arguments. The tool name must"
            echo "  match a name in 'gotools.sh list'. If you installed a tool with an"
            echo "  alias, use that alias here."
            echo ""
            echo "  Examples:"
            echo "    gotools.sh exec gofumpt -w -extra ."
            echo "    gotools.sh exec golangci-lint run ./..."
            ;;
        list)
            echo "Usage: gotools.sh list [--format=json|text]"
            echo ""
            echo "  List all managed tools with their versions and strategy info."
            echo ""
            echo "  Options:"
            echo "    --format=json   Output a JSON object with metadata and a"
            echo "                    \"tools\" array (stable for scripting/CI)"
            echo "    --format=text   Human-readable table (the default)"
            echo "    --json          Alias for --format=json"
            echo "    --text          Alias for --format=text"
            ;;
        info)
            echo "Usage: gotools.sh info <tool-name> [--format=json|text]"
            echo ""
            echo "  Show detailed information about a specific tool."
            echo ""
            echo "  Options:"
            echo "    --format=json   Output a JSON object including a \"runnable\""
            echo "                    flag (stable for scripting/CI)"
            echo "    --format=text   Human-readable block (the default)"
            echo "    --json          Alias for --format=json"
            echo "    --text          Alias for --format=text"
            ;;
        upgrade)
            echo "Usage: gotools.sh upgrade <name|all> [--dry-run]"
            echo ""
            echo "  Upgrade tools to their latest versions."
            echo ""
            echo "  Options:"
            echo "    --dry-run   Show what would be upgraded without making changes"
            echo "    --offline   Refuse to upgrade (needs the network), exit 6"
            ;;
        remove)
            echo "Usage: gotools.sh remove <name1> [name2...] [--dry-run]"
            echo ""
            echo "  Remove specific tools from the project."
            echo ""
            echo "  Options:"
            echo "    --dry-run   Show what would be removed without making changes"
            ;;
        migrate)
            echo "Usage: gotools.sh migrate <unified|split|module> [--dry-run]"
            echo ""
            echo "  Migrate all tools to a different isolation strategy."
            echo "  Preserves exact pinned versions across the migration."
            echo ""
            echo "  Options:"
            echo "    --dry-run   Show what would be migrated without making changes"
            ;;
        config)
            echo "Usage: gotools.sh config [key [value]]"
            echo ""
            echo "  View or edit .gotools.json configuration."
            echo ""
            echo "  No args:    Show the full manifest (cat .gotools.json)"
            echo "  One arg:    Show the value of <key>"
            echo "  Two args:   Set <key>=<value>"
            echo ""
            echo "  Valid keys: GOTOOLS_STRATEGY, GOTOOLS_DIR,"
            echo "              GOTOOLS_GO_VERSION, GOTOOLS_MODULE_PREFIX"
            ;;
        purge)
            echo "Usage: gotools.sh purge [--restore] [--dry-run]"
            echo ""
            echo "  Remove all tools and the .gotools.json manifest."
            echo "  With --restore, the managed tools are added back to the root"
            echo "  go.mod at their pinned versions (go get -tool) before the wipe,"
            echo "  and the init command that recreates this project is printed."
            echo "  Interactive: requires typing YES to confirm."
            echo ""
            echo "  Options:"
            echo "    --restore   Put the managed tools back into the root go.mod"
            echo "    --dry-run   Show what would be removed without deleting"
            ;;
        check)
            echo "Usage: gotools.sh check"
            echo ""
            echo "  Verify all managed tools are installed and runnable."
            echo "  Runs each tool with --help or --version and reports pass/fail."
            ;;
        doctor)
            echo "Usage: gotools.sh doctor [--format=json|text] [--offline]"
            echo ""
            echo "  Diagnose your environment: Go installation, module proxy,"
            echo "  .gotools.json configuration, managed tools, lock file, module"
            echo "  integrity, and disk usage."
            echo ""
            echo "  Read-only: never modifies tools, the manifest, or the lock."
            echo "  Always exits 0 (diagnostics are not failures) — invalid flags"
            echo "  still exit 2. For CI, gate on 'doctor --format=json' and the"
            echo "  \"healthy\"/\"issues\" fields."
            echo ""
            echo "  Options:"
            echo "    --format=json   Output check results as JSON"
            echo "    --format=text   Human-readable report (the default)"
            echo "    --json          Alias for --format=json"
            echo "    --text          Alias for --format=text"
            echo "    --offline       Skip the proxy reachability check; probes fail"
            echo "                    fast instead of touching the network"
            ;;
        version)
            echo "Usage: gotools.sh version [--format=json|text]"
            echo ""
            echo "  Print the gotools.sh version."
            echo ""
            echo "  Options:"
            echo "    --format=json   Output a JSON object (stable for scripting/CI)"
            echo "    --format=text   Plain \"gotools.sh <version>\" line (the default)"
            echo "    --json          Alias for --format=json"
            echo "    --text          Alias for --format=text"
            ;;
        self-update)
            echo "Usage: gotools.sh self-update"
            echo ""
            echo "  Update gotools.sh to the latest release from GitHub."
            echo "  Verifies the release SHA-256 checksum before installing."
            ;;
        uninstall)
            echo "Usage: gotools.sh uninstall"
            echo ""
            echo "  Remove gotools.sh itself from your system."
            ;;
        *)
            usage
            ;;
    esac
}

usage() {
    cat <<EOF
🧰 Go Tool Manager (Version: $VERSION)

Usage: $(basename "$0") <command> [arguments]
       <go install command> | $(basename "$0")     (pipe mode)

Commands:
  init [flags]                      Bootstrap the project and adopt tools
                                    already declared in the root go.mod.
                                      --strategy=unified|split|module  (default: $DEFAULT_STRATEGY)
                                      --dir=<tools-dir>                (default: $DEFAULT_DIR)
                                      --go=<version|inherit>           (default: $DEFAULT_GO_VERSION)
                                      --prefix=<module-prefix|auto>    (default: auto from root go.mod)
                                      --no-migrate --dry-run
  install [name] <pkg>              Install a new tool.
                                    If only <pkg> is given, name is inferred from its basename.
  sync [--dry-run]                  Sync tool state to match $MANIFEST_FILE.
  exec <name> [args]                Run a managed tool.
  list [--format=json|text]         List tools, versions, and strategies.
  upgrade <name|all> [--dry-run]    Upgrade tools to @latest.
  remove <name...> [--dry-run]      Remove specific tools.
  migrate <strategy> [--dry-run]    Migrate to a different strategy.
  config [key [value]]              View or edit $MANIFEST_FILE configuration.
                                      No args: show all config.
                                      One arg: show value of <key>.
                                      Two args: set <key>=<value>.
  purge [--restore] [--dry-run]     Remove all tools and the $MANIFEST_FILE file;
                                    --restore puts the tools back into your go.mod.
  info <name> [--format=json|text]  Show detailed information about a specific tool.
  check                             Verify all managed tools are runnable.
  doctor [--format=json|text] [--offline]
                                    Diagnose your environment (Go, proxy, config,
                                    tools, lock, integrity, disk).
  version [--format=json|text]      Show script version.
  self-update                       Update gotools.sh to the latest version.
  uninstall                         Remove this script from your system.
  test <seconds>                    Sleep for <seconds> (for testing signal handling).

Strategies:
  unified    One shared tools/go.mod with all tool directives.
  split      Flat files: tools/<name>.mod and tools/<name>.sum per tool.
  module     Dedicated subdirectories: tools/<name>/go.mod per tool.

Examples:
  gotools.sh init --strategy=module --dir=tools
  gotools.sh install staticcheck honnef.co/go/tools/cmd/staticcheck@latest
  gotools.sh install golang.org/x/tools/cmd/goimports@latest
  gotools.sh exec goimports -w .
  gotools.sh migrate unified
  gotools.sh upgrade all
  gotools.sh remove staticcheck goimports
  gotools.sh config
  gotools.sh config GOTOOLS_STRATEGY
  gotools.sh config GOTOOLS_STRATEGY module
  gotools.sh purge
  gotools.sh uninstall

Exit Codes:
  \$E_GENERIC             Generic failure (catch-all)
  \$E_USAGE               Usage error — bad flags, wrong args, invalid input
  \$E_NETWORK             Network error — proxy unreachable, DNS failure, timeout
  \$E_LOCK                Lock contention — another gotools process is running
  \$E_TOOL_NOT_FOUND      Tool not installed — run 'gotools.sh sync' and retry
  \$E_OFFLINE             Offline violation — network needed but --offline was set
  \$E_POLICY              Policy violation — tool banned, version not pinned
  \$E_ENVIRONMENT         Environment error — Go missing/too old, bad manifest
EOF
    exit $E_USAGE
}

# ---- check ----------------------------------------------------------------



cmd_check() {
    _require_go
    load_config
    local ok=0 fail=0
    echo "🔍 Checking managed tools..."
    echo ""
    while IFS='|' read -r _n _s _p _v; do
        [[ -z "$_n" ]] && continue
        local status="✅"
        if ! "$0" exec "$_n" --version >/dev/null 2>&1; then
            if ! "$0" exec "$_n" --help >/dev/null 2>&1; then
                if ! "$0" exec "$_n" version >/dev/null 2>&1; then
                    status="❌"
                fi
            fi
        fi
        if [[ "$status" == "✅" ]]; then
            echo "  ✅ $_n ($_p@$_v)"
            ok=$((ok + 1))
        else
            echo "  ❌ $_n ($_p@$_v) — not runnable"
            fail=$((fail + 1))
        fi
    done <<< "$_MANIFEST_TOOLS"
    echo ""
    echo "  $ok passed, $fail failed"
    [[ $fail -eq 0 ]] || return $E_TOOL_NOT_FOUND
}

# ---- completion ----------------------------------------------------------



_generate_bash_completion() {
    cat <<'COMPLETION'
_gotools_completion() {
    local cur prev words cword
    _init_completion || return
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"

    if [[ $COMP_CWORD -eq 1 ]]; then
        COMPREPLY=($(compgen -W "init install sync exec list upgrade update remove migrate config purge info check doctor completion version self-update self-upgrade uninstall help" -- "$cur"))
        return
    fi

    case "$prev" in
        exec|info|remove|upgrade)
            local tools
            tools=$(gotools.sh list 2>/dev/null | awk 'NR>2 && $1!="" {print $1}')
            COMPREPLY=($(compgen -W "$tools" -- "$cur"))
            ;;
        migrate)
            COMPREPLY=($(compgen -W "unified split module" -- "$cur"))
            ;;
        config)
            COMPREPLY=($(compgen -W "GOTOOLS_STRATEGY GOTOOLS_DIR GOTOOLS_GO_VERSION GOTOOLS_MODULE_PREFIX" -- "$cur"))
            ;;
        init)
            COMPREPLY=($(compgen -W "--strategy= --dir= --go= --prefix=" -- "$cur"))
            ;;
        install)
            COMPREPLY=($(compgen -W "--force" -- "$cur"))
            ;;
        completion)
            COMPREPLY=($(compgen -W "bash zsh fish install" -- "$cur"))
            ;;
        sync|upgrade|remove|migrate|purge)
            COMPREPLY=($(compgen -W "--dry-run" -- "$cur"))
            ;;
        list|info|version)
            COMPREPLY=($(compgen -W "--format= --json --text" -- "$cur"))
            ;;
        doctor)
            COMPREPLY=($(compgen -W "--format= --json --text --offline" -- "$cur"))
            ;;
    esac
}
complete -F _gotools_completion gotools.sh gotools
COMPLETION
}

_generate_zsh_completion() {
    cat <<'COMPLETION'
#compdef gotools.sh gotools
_gotools() {
    local -a commands
    commands=(init install sync exec list upgrade update remove migrate config purge info check doctor completion version self-update self-upgrade uninstall help)
    _describe 'command' commands
}
_gotools
COMPLETION
}

_generate_fish_completion() {
    echo "complete -c gotools.sh -f"
    echo "complete -c gotools.sh -a 'init install sync exec list upgrade update remove migrate config purge info check doctor completion version self-update self-upgrade uninstall help'"
    echo "complete -c gotools -f"
    echo "complete -c gotools -a 'init install sync exec list upgrade update remove migrate config purge info check doctor completion version self-update self-upgrade uninstall help'"
}

cmd_completion() {
    local shell="${1:-bash}"

    # install subcommand
    if [[ "$shell" == "install" ]]; then
        cmd_completion_install "${2:-}"
        return
    fi

    case "$shell" in
        bash) _generate_bash_completion ;;
        zsh)  _generate_zsh_completion ;;
        fish) _generate_fish_completion ;;
        *)
            echo "Usage: gotools.sh completion <bash|zsh|fish|install>" >&2
            return $E_USAGE
            ;;
    esac
    echo ""
    echo "# To activate:" >&2
    case "$shell" in
        bash) echo "#   source <(gotools.sh completion bash)" >&2 ;;
        zsh)  echo "#   source <(gotools.sh completion zsh)"  >&2 ;;
        fish) echo "#   gotools.sh completion fish | source"   >&2 ;;
    esac
}

cmd_completion_install() {
    local shell="${1:-}"

    # auto-detect shell from $SHELL if not specified
    if [[ -z "$shell" ]]; then
        case "$SHELL" in
            */bash) shell=bash ;;
            */zsh)  shell=zsh ;;
            */fish) shell=fish ;;
            *)
                echo "❌ Error: Could not detect shell from \$SHELL." >&2
                echo "   Please specify: gotools.sh completion install <bash|zsh|fish>" >&2
                return $E_USAGE
                ;;
        esac
    fi

    local install_path
    case "$shell" in
        bash)
            if [[ -n "${BASH_COMPLETION_USER_DIR:-}" ]]; then
                install_path="$BASH_COMPLETION_USER_DIR/completions/gotools"
            elif [[ -n "${XDG_DATA_HOME:-}" ]]; then
                install_path="$XDG_DATA_HOME/bash-completion/completions/gotools"
            else
                install_path="$HOME/.local/share/bash-completion/completions/gotools"
            fi
            ;;
        zsh)
            install_path="$HOME/.zsh/completions/_gotools"
            ;;
        fish)
            install_path="$HOME/.config/fish/completions/gotools.fish"
            ;;
        *)
            echo "Usage: gotools.sh completion install <bash|zsh|fish>" >&2
            return $E_USAGE
            ;;
    esac

    local dir
    dir=$(dirname "$install_path")
    if [[ ! -d "$dir" ]]; then
        mkdir -p "$dir" || {
            echo "❌ Error: Could not create directory: $dir" >&2
            return $E_GENERIC
        }
    fi

    if [[ -f "$install_path" ]]; then
        echo "📝 Updating existing completion at $install_path"
    else
        echo "✅ Installing completion to $install_path"
    fi

    case "$shell" in
        bash) _generate_bash_completion > "$install_path" ;;
        zsh)  _generate_zsh_completion > "$install_path" ;;
        fish) _generate_fish_completion > "$install_path" ;;
    esac

    echo "✅ Completion installed for $shell: $install_path"

    # post-install hints
    case "$shell" in
        bash)
            echo ""
            echo "💡 To activate, add this to your ~/.bashrc:"
            echo "   source \"$install_path\""
            ;;
        zsh)
            echo ""
            echo "💡 To activate, add this to your ~/.zshrc:"
            echo "   fpath=(\$HOME/.zsh/completions \$fpath)"
            echo "   autoload -Uz compinit && compinit"
            ;;
        fish)
            echo ""
            echo "💡 Fish auto-loads completions from ~/.config/fish/completions/"
            echo "   No further setup needed. Restart your shell or run:"
            echo "   source \"$install_path\""
            ;;
    esac
}

# ---- config --------------------------------------------------------------



cmd_config() {
    # Load the project config first: _manifest_config_set flushes the whole
    # manifest from in-memory state, so without this a write would reset the
    # strategy to the default and wipe the entire tools list.
    load_config

    if [[ $# -eq 0 ]]; then
        # Show all config.
        if [[ ! -f "$MANIFEST_FILE" ]]; then
            echo "⚠️  No $MANIFEST_FILE found. Run 'init' first."
            return $E_ENVIRONMENT
        fi
        cat "$MANIFEST_FILE"
        return 0
    fi

    local key="$1"

    # Validate key name.
    case "$key" in
        GOTOOLS_STRATEGY|GOTOOLS_DIR|GOTOOLS_GO_VERSION|GOTOOLS_MODULE_PREFIX) ;;
        *) echo "❌ Unknown config key: $key" >&2
           echo "   Valid keys: GOTOOLS_STRATEGY, GOTOOLS_DIR, GOTOOLS_GO_VERSION, GOTOOLS_MODULE_PREFIX" >&2
           return $E_USAGE ;;
    esac

    if [[ $# -eq 1 ]]; then
        # Show single key.
        if [[ ! -f "$MANIFEST_FILE" ]]; then
            echo "⚠️  No $MANIFEST_FILE found. Run 'init' first."
            return $E_ENVIRONMENT
        fi
        local val
        val=$(_manifest_config_get "$key")
        if [[ -n "$val" ]]; then
            echo "$val"
        else
            echo "⚠️  $key is not set. (auto-detected from root go.mod when empty)"
        fi
        return 0
    fi

    local value="$2"

    # Validate value for strategy key.
    if [[ "$key" == "GOTOOLS_STRATEGY" ]]; then
        case "$value" in
            unified|split|module) ;;
            *) echo "❌ Invalid strategy: $value (must be unified, split, or module)" >&2; return $E_USAGE ;;
        esac
    fi

    if [[ ! -f "$MANIFEST_FILE" ]]; then
        # Create a new manifest with this one key set.
        GOTOOLS_STRATEGY="${DEFAULT_STRATEGY}"
        GOTOOLS_DIR="${DEFAULT_DIR}"
        GOTOOLS_GO_VERSION="${DEFAULT_GO_VERSION}"
        GOTOOLS_MODULE_PREFIX="${DEFAULT_MODULE_PREFIX}"
        _MANIFEST_TOOLS=""
        _manifest_config_set "$key" "$value"
        echo "✅ Created $MANIFEST_FILE with $key=$value"
        return 0
    fi

    _manifest_config_set "$key" "$value"
    echo "✅ Set $key=$value"

    # Warn if strategy was changed — sync is needed to migrate tools.
    if [[ "$key" == "GOTOOLS_STRATEGY" ]]; then
        echo "⚠️  Strategy changed. Run 'gotools.sh sync' to migrate the tools directory."
    fi
}

# ---------------------------------------------------------------------------
# doctor — systematic environment diagnostics (issue #28)
#
# Seven checks: Go installation, module proxy, configuration, managed tools,
# lock file, module integrity, and disk usage. Read-only: doctor never
# acquires the lock (it inspects it), never writes the manifest, the sync
# fingerprint, or a trace record. Probes set GOTOOLCHAIN=local (no toolchain
# auto-download) and GOPROXY=off in offline mode (fail fast, no network).
#
# Exit code is ALWAYS 0 (pure diagnostics) — invalid flags still exit
# E_USAGE. CI gates on `doctor --format=json` → healthy/issues.
# ---------------------------------------------------------------------------

# Result store: pipe-delimited name|status|detail lines, one per check.
# _doctor_add_result appends; single-result checks go through
# _doctor_run_check (subshell capture), the multi-result tools check runs in
# the main shell and appends directly.
_doctor_add_result() {
    local name="$1" status="$2" detail="$3"
    _DOCTOR_RESULTS+="${name}|${status}|${detail}"$'\n'
}

# _doctor_run_check <name> <check-fn>
#   Runs check-fn in a subshell: it prints a one-line detail to stdout and
#   returns 0=pass, 1=warn, 2=fail, anything else=skip. Check fns must be
#   pure — mutations made inside the subshell are lost. OR-list capture keeps
#   set -e from killing the script on a failing check. Always returns 0.
_doctor_run_check() {
    local name="$1" fn="$2"
    local detail rc=0
    detail=$("$fn") || rc=$?
    local status
    case "$rc" in
        0) status="pass" ;;
        1) status="warn" ;;
        2) status="fail" ;;
        *) status="skip" ;;
    esac
    detail="${detail%%$'\n'*}"
    _doctor_add_result "$name" "$status" "$detail"
}

# ---- check: Go installation ---------------------------------------------
_doctor_check_go() {
    local go_path
    go_path=$(command -v go 2>/dev/null) || { echo "Go not installed. Install Go $MIN_GO_VERSION or higher (https://go.dev/dl/)."; return 2; }
    local ver
    ver=$(_go env GOVERSION 2>/dev/null | sed 's/^go//') || true
    if [[ -z "$ver" ]]; then
        echo "Could not determine Go version."
        return 2
    fi
    if ! _version_meets_min "$ver" "$MIN_GO_VERSION"; then
        echo "Go $ver is too old. Go $MIN_GO_VERSION or higher is required."
        return 2
    fi
    echo "Go $ver at $go_path — meets minimum ($MIN_GO_VERSION+)"
    return 0
}

# ---- check: module proxy -------------------------------------------------
_doctor_check_proxy() {
    command -v go >/dev/null 2>&1 || { echo "go not installed"; return 3; }
    if $_OFFLINE; then echo "offline mode — reachability not checked"; return 3; fi
    local goproxy
    goproxy=$(_go env GOPROXY 2>/dev/null) || { echo "could not read GOPROXY (go env failed)"; return 1; }
    # First declared tool (string slicing — a pipeline could trip pipefail).
    local entry="${_MANIFEST_TOOLS%%$'\n'*}" tname="" src="" pkg="" probe=""
    if [[ -n "$entry" ]]; then
        IFS='|' read -r tname src pkg _ <<< "$entry"
        if [[ "$src" == "go" && -n "$pkg" ]]; then
            # Resolve the module root from the tool's modfile require block
            # (no network): many tool packages are subpackages of a module
            # (golang.org/x/tools/cmd/goimports → golang.org/x/tools), and
            # `go list -m` only accepts module paths. @latest, not @version:
            # the pinned version may be cache-served, but @latest always
            # queries the proxy — a real reachability probe.
            local modfile=""
            case "$GOTOOLS_STRATEGY" in
                unified) modfile="$GOTOOLS_DIR/go.mod" ;;
                split)   modfile="$GOTOOLS_DIR/${tname}.mod" ;;
                module)  modfile="$GOTOOLS_DIR/${tname}/go.mod" ;;
            esac
            if [[ -f "$modfile" ]]; then
                local module_root
                module_root=$(extract_module_for_pkg "$modfile" "$pkg" 2>/dev/null) || true
                [[ -n "$module_root" ]] && probe="${module_root}@latest"
            fi
        fi
    fi
    if [[ -z "$probe" ]]; then
        echo "GOPROXY=${goproxy:-<unset — Go default>} (no tool to probe — reachability not checked)"
        return 0
    fi
    # `go list -m` accepts no -timeout flag, so bound the probe with a 5s
    # watchdog: kill the go process if it outlives the budget.
    local out_file rc=0
    out_file=$(mktemp "${TMPDIR:-/tmp}/gotools-doctor-proxy.XXXXXX") || { echo "could not create probe temp file"; return 1; }
    ( export GOTOOLCHAIN=local; _go list -m "$probe" >"$out_file" 2>&1 ) &
    local pid=$! waited=0
    while kill -0 "$pid" 2>/dev/null; do
        if [[ $waited -ge 10 ]]; then
            kill "$pid" 2>/dev/null
            echo "GOPROXY=$goproxy — unreachable (no answer within 5s)"
            rm -f "$out_file"
            return 1
        fi
        sleep 0.5
        waited=$((waited + 1))
    done
    # `wait` inherits the child's exit status — OR-guard it (set -e).
    wait "$pid" 2>/dev/null || rc=$?
    local first=""
    first=$(head -n1 "$out_file" 2>/dev/null || true)
    rm -f "$out_file"
    if [[ $rc -ne 0 ]]; then
        echo "GOPROXY=$goproxy — unreachable: ${first:-unknown error}"
        return 1
    fi
    echo "GOPROXY=$goproxy — reachable"
    return 0
}

# ---- check: configuration -------------------------------------------------
_doctor_check_config() {
    if [[ $_DOCTOR_BAD_MANIFEST -eq 1 ]]; then
        echo "${_DOCTOR_MANIFEST_REASON:-$MANIFEST_FILE is invalid}"
        return 2
    fi
    if [[ ! -f "$MANIFEST_FILE" ]]; then
        echo "no $MANIFEST_FILE — run 'gotools init'"
        return 2
    fi
    echo "$MANIFEST_FILE exists and is valid (schema v$_MANIFEST_SCHEMA_VERSION)"
    return 0
}

# ---- check: strategy matches disk -----------------------------------------
_doctor_check_strategy() {
    if [[ $_DOCTOR_BAD_MANIFEST -eq 1 || ! -f "$MANIFEST_FILE" ]]; then
        echo "cannot compare strategy — manifest missing or invalid"
        return 3
    fi
    local detected
    detected=$(detect_strategy "$GOTOOLS_DIR" 2>/dev/null) || true
    if [[ ! -d "$GOTOOLS_DIR" || -z "$detected" ]]; then
        echo "tools not synced — run 'gotools sync'"
        return 1
    fi
    if [[ "$detected" != "$GOTOOLS_STRATEGY" ]]; then
        echo "Strategy: $GOTOOLS_STRATEGY — disk looks like $detected (run 'gotools sync' to migrate)"
        return 1
    fi
    echo "Strategy: $GOTOOLS_STRATEGY — matches disk"
    return 0
}

# ---- check: managed tools --------------------------------------------------
# Multi-result: runs in the MAIN shell (subshell captures would lose the
# result-store mutations), so it appends directly via _doctor_add_result.
_doctor_check_tools() {
    local _n _s _p _v count=0
    while IFS='|' read -r _n _s _p _v; do
        [[ -z "$_n" ]] && continue
        count=$((count + 1))
        if [[ "$_s" != "go" ]]; then
            _doctor_add_result "tools.$_n" "skip" "$_n@$_v — source '$_s' not probed"
            continue
        fi
        local reason rc=0
        reason=$(tool_runnable "$_n" 2>/dev/null) || rc=$?
        if [[ $rc -eq 0 ]]; then
            _doctor_add_result "tools.$_n" "pass" "$_n@$_v — runnable"
        else
            _doctor_add_result "tools.$_n" "warn" "$_n@$_v — not runnable: ${reason:-unknown} (run 'gotools sync')"
        fi
    done <<< "$_MANIFEST_TOOLS"
    if [[ $count -eq 0 ]]; then
        _doctor_add_result "tools" "pass" "no tools declared"
    fi
}

# ---- check: lock file ------------------------------------------------------
# stat flags differ per platform: BSD (macOS) uses -f, GNU (Linux) uses -c.
_file_mtime() {
    case "$(uname -s)" in
        Darwin) stat -f %m "$1" ;;
        *)      stat -c %Y "$1" ;;
    esac
}

_doctor_check_lock() {
    local lock_dir="$GOTOOLS_DIR/.gotools.lock"
    [[ -d "$lock_dir" ]] || { echo "no lock detected"; return 0; }
    local now mtime age
    now=$(date +%s)
    mtime=$(_file_mtime "$lock_dir" 2>/dev/null) || true
    if [[ -z "$mtime" ]]; then
        echo "unable to read lock age"
        return 1
    fi
    age=$((now - mtime))
    if [[ $age -gt 300 ]]; then
        echo "stale lock directory (age ${age}s) — remove $lock_dir if no gotools process is running"
        return 1
    fi
    echo "lock is held or was released recently (age ${age}s) — another gotools process may be running"
    return 0
}

# ---- check: module integrity ------------------------------------------------
_doctor_check_integrity() {
    command -v go >/dev/null 2>&1 || { echo "go not installed"; return 3; }
    local out rc=0 count=0
    case "$GOTOOLS_STRATEGY" in
        unified)
            local mf="$GOTOOLS_DIR/go.mod"
            if [[ ! -f "$mf" ]]; then echo "no $mf — run 'gotools sync'"; return 3; fi
            if [[ ! -f "$GOTOOLS_DIR/go.sum" ]]; then echo "missing $GOTOOLS_DIR/go.sum — run 'gotools sync'"; return 2; fi
            out=$( (export GOTOOLCHAIN=local; $_OFFLINE && export GOPROXY=off; cd "$GOTOOLS_DIR" && _go mod verify) 2>&1 ) || rc=$?
            if [[ $rc -ne 0 ]]; then
                echo "go mod verify failed for $mf: ${out%%$'\n'*}"
                return 2
            fi
            echo "go mod verify passed for all 1 modules"
            return 0
            ;;
        split)
            local f name sumf
            for f in "$GOTOOLS_DIR"/*.mod; do
                [[ -f "$f" ]] || continue
                count=$((count + 1))
                name=$(basename "$f" .mod)
                sumf="$GOTOOLS_DIR/${name}.sum"
                if [[ ! -f "$sumf" ]]; then
                    echo "missing $sumf — run 'gotools sync'"
                    return 2
                fi
                out=$( (export GOTOOLCHAIN=local; $_OFFLINE && export GOPROXY=off; _go mod verify -modfile="$f") 2>&1 ) || rc=$?
                if [[ $rc -ne 0 ]] && [[ "$out" == *"flag provided but not defined"* ]]; then
                    # Older go: `go mod verify` may not know -modfile — retry
                    # through GOFLAGS, which every go command honors.
                    rc=0
                    out=$( (export GOTOOLCHAIN=local GOFLAGS="-modfile=$f"; $_OFFLINE && export GOPROXY=off; _go mod verify) 2>&1 ) || rc=$?
                fi
                if [[ $rc -ne 0 ]]; then
                    echo "go mod verify failed for $f: ${out%%$'\n'*}"
                    return 2
                fi
            done
            if [[ $count -eq 0 ]]; then echo "no tool modfiles in $GOTOOLS_DIR — run 'gotools sync'"; return 3; fi
            echo "go mod verify passed for all $count modules"
            return 0
            ;;
        module)
            local d mf2
            for d in "$GOTOOLS_DIR"/*/; do
                [[ -d "$d" ]] || continue
                mf2="$d/go.mod"
                [[ -f "$mf2" ]] || continue
                count=$((count + 1))
                if [[ ! -f "$d/go.sum" ]]; then
                    echo "missing ${d}go.sum — run 'gotools sync'"
                    return 2
                fi
                out=$( (export GOTOOLCHAIN=local; $_OFFLINE && export GOPROXY=off; cd "$d" && _go mod verify) 2>&1 ) || rc=$?
                if [[ $rc -ne 0 ]]; then
                    echo "go mod verify failed for $mf2: ${out%%$'\n'*}"
                    return 2
                fi
            done
            if [[ $count -eq 0 ]]; then echo "no tool modules in $GOTOOLS_DIR — run 'gotools sync'"; return 3; fi
            echo "go mod verify passed for all $count modules"
            return 0
            ;;
        *)
            echo "unknown strategy: $GOTOOLS_STRATEGY"
            return 3
            ;;
    esac
}

# ---- check: disk usage -------------------------------------------------------
_doctor_check_disk() {
    [[ -d "$GOTOOLS_DIR" ]] || { echo "tools directory not found"; return 3; }
    local size
    size=$(du -sh "$GOTOOLS_DIR" 2>/dev/null | awk '{print $1}') || { echo "unable to measure disk usage"; return 3; }
    echo "tools/ uses $size"
    return 0
}

# ---- renderers ----------------------------------------------------------------
_doctor_heading() {
    case "$1" in
        go)        echo "Go installation" ;;
        proxy)     echo "Module proxy" ;;
        config)    echo "Configuration" ;;
        tools)     echo "Managed tools" ;;
        lock)      echo "Lock file" ;;
        integrity) echo "Module integrity" ;;
        disk)      echo "Disk usage" ;;
        *)         echo "$1" ;;
    esac
}

_doctor_render_text() {
    local name status detail grp="" issues=0 tool_count=0
    while IFS='|' read -r name _ _; do
        [[ "$name" == tools.* ]] && tool_count=$((tool_count + 1))
    done <<< "$_DOCTOR_RESULTS"
    while IFS='|' read -r name status detail; do
        [[ -n "$name" ]] || continue
        local g="${name%%.*}" icon=""
        if [[ "$g" != "$grp" ]]; then
            if [[ -n "$grp" ]]; then echo ""; fi
            local heading
            heading=$(_doctor_heading "$g")
            if [[ "$g" == "tools" && $tool_count -gt 0 ]]; then
                echo "  $heading ($tool_count declared)"
            else
                echo "  $heading"
            fi
            grp="$g"
        fi
        case "$status" in
            pass) icon="✅" ;;
            warn) icon="⚠️" ;;
            fail) icon="❌" ;;
            skip) icon="⏭" ;;
        esac
        if [[ -n "$detail" ]]; then
            echo "  $icon $detail"
        else
            echo "  $icon"
        fi
        if [[ "$status" == "warn" || "$status" == "fail" ]]; then
            issues=$((issues + 1))
        fi
    done <<< "$_DOCTOR_RESULTS"
    echo ""
    echo "──────────────────────────────────────────────────"
    if [[ $issues -eq 0 ]]; then
        echo "✅ All checks passed. Your environment is healthy."
    elif [[ $issues -eq 1 ]]; then
        echo "⚠️ 1 issue found."
    else
        echo "⚠️ $issues issues found."
    fi
}

_doctor_render_json() {
    local name status detail issues=0
    while IFS='|' read -r name status detail; do
        [[ -n "$name" ]] || continue
        if [[ "$status" == "warn" || "$status" == "fail" ]]; then
            issues=$((issues + 1))
        fi
    done <<< "$_DOCTOR_RESULTS"
    if [[ $issues -eq 0 ]]; then
        printf '{"schema_version":1,"healthy":true,"issues":0,"checks":['
    else
        printf '{"schema_version":1,"healthy":false,"issues":%d,"checks":[' "$issues"
    fi
    local sep=""
    while IFS='|' read -r name status detail; do
        [[ -n "$name" ]] || continue
        printf '%s{"name":"%s","status":"%s"' "$sep" "$(_json_escape "$name")" "$status"
        if [[ -n "$detail" ]]; then
            printf ',"detail":"%s"' "$(_json_escape "$detail")"
        fi
        printf '}'
        sep=","
    done <<< "$_DOCTOR_RESULTS"
    printf ']}\n'
}

# ---- doctor -----------------------------------------------------------------
cmd_doctor() {
    _parse_offline "$@"
    _parse_output_format "$@"
    local arg
    for arg in "$@"; do
        case "$arg" in
            --offline|--json|--text|--format=json|--format=text) ;;
            *)
                echo "❌ Unknown argument: $arg" >&2
                echo "   Usage: $(basename "$0") doctor [--format=json|text] [--offline]" >&2
                exit $E_USAGE
                ;;
        esac
    done

    _DOCTOR_RESULTS=""
    _DOCTOR_BAD_MANIFEST=0
    _DOCTOR_MANIFEST_REASON=""

    # load_config EXITS on a manifest written by a newer gotools — pre-validate
    # and bypass it so doctor can still render a full report.
    _find_project_root
    if [[ -f "$MANIFEST_FILE" ]]; then
        local mrc=0 verr=""
        verr=$(_manifest_validate "$MANIFEST_FILE" 2>&1 >/dev/null) || mrc=$?
        if [[ $mrc -ne 0 ]]; then
            _DOCTOR_BAD_MANIFEST=1
            _DOCTOR_MANIFEST_REASON="${verr%%$'\n'*}"
            # Replicate load_config's env > default precedence without parsing
            # the broken file; mark config loaded so nested calls no-op.
            GOTOOLS_STRATEGY="${_ORIG_ENV_STRATEGY:-$DEFAULT_STRATEGY}"
            GOTOOLS_DIR="${_ORIG_ENV_DIR:-$DEFAULT_DIR}"
            GOTOOLS_GO_VERSION="${_ORIG_ENV_GO_VERSION:-$DEFAULT_GO_VERSION}"
            GOTOOLS_MODULE_PREFIX=""
            _CONFIG_LOADED=true
        else
            load_config
        fi
    else
        load_config
    fi

    if [[ "$_OUTPUT_FORMAT" != "json" ]]; then
        echo "🔍 gotools doctor — checking your environment..."
        echo ""
    fi

    _doctor_run_check "go" _doctor_check_go
    _doctor_run_check "proxy" _doctor_check_proxy
    _doctor_run_check "config" _doctor_check_config
    _doctor_run_check "config.strategy" _doctor_check_strategy
    _doctor_check_tools
    _doctor_run_check "lock" _doctor_check_lock
    _doctor_run_check "integrity" _doctor_check_integrity
    _doctor_run_check "disk" _doctor_check_disk

    if [[ "$_OUTPUT_FORMAT" == "json" ]]; then
        _doctor_render_json
    else
        _doctor_render_text
    fi
    # Always exit 0: doctor is pure diagnostics — check results never fail
    # the shell. Invalid flags exited E_USAGE above. CI gates on
    # `doctor --format=json` → healthy/issues.
}
# ---- exec ----------------------------------------------------------------
cmd_exec() {
    _require_go
    load_config
    local tool_name="${1:?tool name is required}"
    shift

    case "$GOTOOLS_STRATEGY" in
        unified)
            if [[ ! -f "$GOTOOLS_DIR/go.mod" ]]; then
                _trace_fatal "No $GOTOOLS_DIR/go.mod found" "$tool_name"
                echo "❌ Error: No $GOTOOLS_DIR/go.mod found. Run 'init' first." >&2
                exit $E_TOOL_NOT_FOUND
            fi
            local binary
            binary=$(resolve_binary_name "$tool_name" "$GOTOOLS_DIR/go.mod")
            local _ec=0
            (cd "$GOTOOLS_DIR" && go tool "$binary" "$@") || _ec=$?
            _trace_exec "$binary" "$_ec" "$tool_name" "$@"
            exit $_ec
            ;;

        split)
            local mod_file="$GOTOOLS_DIR/${tool_name}.mod"
            if [[ ! -f "$mod_file" ]]; then
                _trace_fatal "Tool '$tool_name' not found ($mod_file missing)" "$tool_name"
                echo "❌ Error: Tool '$tool_name' not found ($mod_file missing). Run 'install' first." >&2
                exit $E_TOOL_NOT_FOUND
            fi
            local binary
            binary=$(resolve_binary_name "$tool_name" "$mod_file")
            local _ec=0
            go tool -modfile="$mod_file" "$binary" "$@" || _ec=$?
            _trace_exec "$binary" "$_ec" "$tool_name" "$@"
            exit $_ec
            ;;

        module)
            if [[ ! -d "$GOTOOLS_DIR/$tool_name" ]]; then
                _trace_fatal "Tool '$tool_name' not found ($GOTOOLS_DIR/$tool_name missing)" "$tool_name"
                echo "❌ Error: Tool '$tool_name' not found ($GOTOOLS_DIR/$tool_name missing). Run 'install' first." >&2
                exit $E_TOOL_NOT_FOUND
            fi
            local binary
            binary=$(resolve_binary_name "$tool_name" "$GOTOOLS_DIR/$tool_name/go.mod")
            local _ec=0
            (cd "$GOTOOLS_DIR/$tool_name" && go tool "$binary" "$@") || _ec=$?
            _trace_exec "$binary" "$_ec" "$tool_name" "$@"
            exit $_ec
            ;;

        *)
            _trace_fatal "Unknown strategy: $GOTOOLS_STRATEGY" "$tool_name"
            echo "❌ Unknown strategy: $GOTOOLS_STRATEGY" >&2
            exit $E_ENVIRONMENT
            ;;
    esac
}

# _info_json <tool-name> — output a single tool as a JSON object with a
# runnable flag (probed only when the tool's modfile exists; otherwise false
# without invoking go).

_info_json() {
    local name="$1"
    local entry
    entry=$(_manifest_tool_entry "$name" 2>/dev/null || true)
    if [[ -z "$entry" ]]; then
        echo "{\"error\":\"tool not found: $name\"}"
        return 1
    fi
    local _s _p _v
    _s=$(echo "$entry" | cut -d'|' -f1)
    _p=$(echo "$entry" | cut -d'|' -f2)
    _v=$(echo "$entry" | cut -d'|' -f3)
    local go_ver="?"
    case "$GOTOOLS_STRATEGY" in
        unified) go_ver=$(extract_go_version_from_mod "$GOTOOLS_DIR/go.mod" 2>/dev/null || echo "?") ;;
        split)   go_ver=$(extract_go_version_from_mod "$GOTOOLS_DIR/${name}.mod" 2>/dev/null || echo "?") ;;
        module)  go_ver=$(extract_go_version_from_mod "$GOTOOLS_DIR/${name}/go.mod" 2>/dev/null || echo "?") ;;
    esac
    local runnable=false
    local modfile=""
    case "$GOTOOLS_STRATEGY" in
        unified) modfile="$GOTOOLS_DIR/go.mod" ;;
        split)   modfile="$GOTOOLS_DIR/${name}.mod" ;;
        module)  modfile="$GOTOOLS_DIR/${name}/go.mod" ;;
    esac
    if [[ -f "$modfile" ]] && tool_runnable "$name" >/dev/null 2>&1; then
        runnable=true
    fi
    printf '{"schema_version":1,"name":"%s","source":"%s","strategy":"%s","go":"%s","package":"%s","version":"%s","runnable":%s}\n' \
        "$(_json_escape "$name")" "$(_json_escape "$_s")" "$(_json_escape "$GOTOOLS_STRATEGY")" \
        "$(_json_escape "$go_ver")" "$(_json_escape "$_p")" "$(_json_escape "$_v")" "$runnable"
}

# ---- info ----------------------------------------------------------------
cmd_info() {
    load_config
    _parse_output_format "$@"
    local -a positional
    positional=()
    local arg
    for arg in "$@"; do
        case "$arg" in
            --json|--text|--format=json|--format=text) ;;
            *) positional+=("$arg") ;;
        esac
    done

    if [[ ${#positional[@]} -eq 0 || ${#positional[@]} -gt 1 ]]; then
        echo "❌ Usage: $(basename "$0") info <tool-name> [--format=json|text]" >&2
        exit $E_USAGE
    fi

    local tool_name="${positional[0]}"

    if [[ "$_OUTPUT_FORMAT" == "json" ]]; then
        _info_json "$tool_name" || exit $E_TOOL_NOT_FOUND
        return
    fi

    local modfile="" pkg="" ver="" go_ver="" strategy="$GOTOOLS_STRATEGY"

    case "$GOTOOLS_STRATEGY" in
        unified)
            modfile="$GOTOOLS_DIR/go.mod"
            if [[ ! -f "$modfile" ]]; then
                echo "❌ No $modfile found. Run 'init' first." >&2
                exit $E_TOOL_NOT_FOUND
            fi
            # Find the package whose inferred name matches the tool name.
            pkg=$(extract_tools_from_mod "$modfile" | while IFS= read -r p; do
                if [[ "$(infer_binary_name_from_pkg "$p")" == "$tool_name" ]]; then
                    echo "$p"
                    break
                fi
            done)
            if [[ -z "$pkg" ]]; then
                echo "❌ Tool '$tool_name' not found in $modfile." >&2
                exit $E_TOOL_NOT_FOUND
            fi
            ver=$(extract_version_for_pkg "$modfile" "$pkg")
            go_ver=$(extract_go_version_from_mod "$modfile")
            ;;

        split)
            modfile="$GOTOOLS_DIR/${tool_name}.mod"
            if [[ ! -f "$modfile" ]]; then
                echo "❌ Tool '$tool_name' not found ($modfile missing)." >&2
                exit $E_TOOL_NOT_FOUND
            fi
            pkg=$(extract_pkg_from_mod "$modfile")
            ver=$(extract_version_for_pkg "$modfile" "$pkg")
            go_ver=$(extract_go_version_from_mod "$modfile")
            ;;

        module)
            modfile="$GOTOOLS_DIR/$tool_name/go.mod"
            if [[ ! -f "$modfile" ]]; then
                echo "❌ Tool '$tool_name' not found ($modfile missing)." >&2
                exit $E_TOOL_NOT_FOUND
            fi
            pkg=$(extract_pkg_from_mod "$modfile")
            ver=$(extract_version_for_pkg "$modfile" "$pkg")
            go_ver=$(extract_go_version_from_mod "$modfile")
            ;;

        *)
            echo "❌ Unknown strategy: $GOTOOLS_STRATEGY" >&2
            exit $E_ENVIRONMENT
            ;;
    esac

    local rel_mod src
    rel_mod=$(relative_path "$modfile")
    src=$(_manifest_tool_entry "$tool_name" 2>/dev/null | cut -d'|' -f1)

    echo ""
    echo "  Tool:       $tool_name"
    echo "  Source:     ${src:-go}"
    echo "  Package:    ${pkg:-unknown}"
    echo "  Version:    ${ver:-unknown}"
    echo "  Go:         ${go_ver:-unknown}"
    echo "  Strategy:   $strategy"
    echo "  Modfile:    $rel_mod"
    echo ""
}
# ---- init ----------------------------------------------------------------

# _gomod_migrate <root-modfile>
#   Adopt the tools already declared in the project's root go.mod:
#   scan -> install (additive) -> strip -> tidy. The root go.mod is not
#   modified until every tool has been installed successfully, so a failed
#   migration leaves the project exactly as it was and a re-run resumes.
_gomod_migrate() {
    local root_mod="$1"
    local scan
    scan=$(_gomod_tool_scan "$root_mod")

    if [[ -z "$scan" ]]; then
        echo "ℹ No tool directives in go.mod — nothing to migrate."
        return 0
    fi

    local count
    count=$(wc -l <<< "$scan" | tr -d ' ')
    echo "🔍 Found $count tool(s) in go.mod:"
    while IFS=' ' read -r name pkg_at_version; do
        echo "     $name  $pkg_at_version"
    done <<< "$scan"

    # Phase 2 — install (additive; root go.mod untouched until this succeeds)
    while IFS=' ' read -r name pkg_at_version; do
        [[ -z "$name" ]] && continue
        if _manifest_tool_exists "$name"; then
            echo "  ⏭ $name — already managed, skipping"
            continue
        fi
        if $_DRY_RUN; then
            echo "  [dry-run] Would install $name ($pkg_at_version)"
            continue
        fi
        cmd_install "$name" "$pkg_at_version"
    done <<< "$scan"

    # Phases 3–4 — destructive to root go.mod, only after installs succeeded
    if $_DRY_RUN; then
        echo "[dry-run] Would strip tool directives from go.mod and run 'go mod tidy'."
        return 0
    fi

    echo "✂️  Removing tool directives from go.mod..."
    local tmp="$root_mod.tmp.$$"
    strip_tools_from_mod "$root_mod" > "$tmp"
    mv "$tmp" "$root_mod"

    echo "🧹 Running 'go mod tidy' on the root module..."
    _go mod tidy

    echo "✅ Migrated $count tool(s) from go.mod into gotools."
}

cmd_init() {
    local strategy=$DEFAULT_STRATEGY dir=$DEFAULT_DIR go_v=$DEFAULT_GO_VERSION prefix=""
    local no_migrate=false
    for arg in "$@"; do
        case $arg in
            --strategy=*) strategy="${arg#*=}" ;;
            --dir=*)      dir="${arg#*=}" ;;
            --go=*)       go_v="${arg#*=}" ;;
            --prefix=*)   prefix="${arg#*=}" ;;
            --no-migrate) no_migrate=true ;;
            --dry-run)    _DRY_RUN=true ;;
            *)            echo "❓ Unknown flag: $arg"; usage ;;
        esac
    done

    # Validate strategy.
    case "$strategy" in
        unified|split|module) ;;
        *) echo "❌ Invalid strategy: $strategy (must be unified, split, or module)" >&2; exit $E_USAGE ;;
    esac

    # Load the existing manifest FIRST so re-running init merges the tool
    # list instead of wiping it.
    load_config

    # Set config vars (flags/defaults win), then flush.
    GOTOOLS_STRATEGY="$strategy"
    GOTOOLS_DIR="$dir"
    GOTOOLS_GO_VERSION="$go_v"
    GOTOOLS_MODULE_PREFIX="$prefix"
    if $_DRY_RUN; then
        echo "🔍 [dry-run] Would write $MANIFEST_FILE (strategy=$strategy, dir=$dir)"
    else
        _manifest_flush
        mkdir -p "$dir"
        echo "✅ Initialized $MANIFEST_FILE (strategy=$strategy, dir=$dir)"
    fi

    # Adopt tools already declared in the root go.mod (unless --no-migrate).
    if ! $no_migrate; then
        local root_mod="$_PROJECT_ROOT/go.mod"
        if [[ -f "$root_mod" ]]; then
            _gomod_migrate "$root_mod"
        else
            echo "ℹ No go.mod in project root — skipping tool migration."
        fi
    fi

    # Reconcile; pass --dry-run through so a dry-run init stays read-only.
    if $_DRY_RUN; then
        cmd_sync --dry-run
    else
        cmd_sync
    fi
}

# _install_failed <name> <output> — report a failed `go get -tool` and exit
# with a structured exit code. Network problems (proxy unreachable, DNS
# failure, timeout) exit $E_NETWORK so CI can retry with backoff; invalid
# package paths / versions are usage errors and exit $E_USAGE; anything
# else exits $E_GENERIC.



_install_failed() {
    local name="$1" output="$2"
    echo "❌ Failed to install $name" >&2
    [[ -n "$output" ]] && echo "$output" >&2
    if echo "$output" | grep -qiE 'dial tcp|i/o timeout|connection timed out|no such host|connection refused|network is unreachable|could not resolve host|fetch failed|timeout exceeded'; then
        exit $E_NETWORK
    fi
    if echo "$output" | grep -qiE 'invalid module version syntax|malformed module path|invalid package path|can.t request version'; then
        exit $E_USAGE
    fi
    exit $E_GENERIC
}

# ---- install -------------------------------------------------------------
cmd_install() {
    _require_go
    load_config
    _acquire_lock

    # Strip --force/--offline from args before parsing name/pkg.
    local force=false filtered=()
    for a in "$@"; do
        if [[ "$a" == "--force" ]]; then force=true
        elif [[ "$a" == "--offline" ]]; then _OFFLINE=true
        else filtered+=("$a"); fi
    done
    _parse_offline "$@"
    # ${filtered[@]+...} keeps the expansion legal when filtered is empty
    # under `set -u` on bash < 4.4 (e.g. plain `gotools.sh install`).
    set -- ${filtered[@]+"${filtered[@]}"}

    local name="" pkg="" _get_out=""
    if [[ $# -eq 0 ]]; then
        echo "❌ Usage: $(basename "$0") install [name] <pkg> [--force]" >&2
        exit $E_USAGE
    elif [[ $# -eq 1 ]]; then
        pkg="$1"
        name=$(infer_binary_name_from_pkg "${pkg%%@*}")
    else
        name="$1"
        pkg="$2"
    fi

    # Installing a new tool needs the module proxy — refuse in offline mode.
    if ${_OFFLINE:-false}; then
        echo "❌ Offline mode: cannot install new tools without network." >&2
        exit $E_OFFLINE
    fi

    local target_v
    target_v=$(resolve_go_version)

    # refuse duplicate tool names unless --force is given.
    if _manifest_tool_exists "$name" && ! $force; then
        echo "❌ Tool '$name' already exists in manifest. Use --force to overwrite." >&2
        exit $E_USAGE
    fi

    echo "📦 Installing $name ($pkg) [strategy=$GOTOOLS_STRATEGY]..."

    local _created_mod=false  # track whether we just created a mod file/dir
    case "$GOTOOLS_STRATEGY" in
        unified)
            mkdir -p "$GOTOOLS_DIR"
            if [[ ! -f "$GOTOOLS_DIR/go.mod" ]]; then
                (cd "$GOTOOLS_DIR" && go mod init "$(tool_module_path)" && go mod edit -go="$target_v")
            fi
            if ! _get_out=$(cd "$GOTOOLS_DIR" && go get -tool "$pkg" 2>&1); then
                _install_failed "$name" "$_get_out"
            fi
            ;;

        split)
            mkdir -p "$GOTOOLS_DIR"
            local modfile="${name}.mod"
            if [[ ! -f "$GOTOOLS_DIR/$modfile" ]]; then
                _created_mod=true
                local mod_path
                mod_path=$(tool_module_path "$name")
                cat > "$GOTOOLS_DIR/$modfile" <<MODEOF
module $mod_path

go $target_v
MODEOF
            fi
            if ! _get_out=$(cd "$GOTOOLS_DIR" && go get -tool -modfile="$modfile" "$pkg" 2>&1); then
                if $_created_mod; then
                    rm -f "$GOTOOLS_DIR/$modfile" "$GOTOOLS_DIR/${modfile%.mod}.sum"
                fi
                _install_failed "$name" "$_get_out"
            fi
            ;;

        module)
            mkdir -p "$GOTOOLS_DIR/$name"
            if [[ ! -f "$GOTOOLS_DIR/$name/go.mod" ]]; then
                _created_mod=true
                (cd "$GOTOOLS_DIR/$name" && go mod init "$(tool_module_path "$name")" && go mod edit -go="$target_v")
            fi
            if ! _get_out=$(cd "$GOTOOLS_DIR/$name" && go get -tool "$pkg" 2>&1); then
                if $_created_mod; then
                    rm -rf "${GOTOOLS_DIR:?}/$name"
                fi
                _install_failed "$name" "$_get_out"
            fi
            ;;

        *)
            echo "❌ Unknown strategy: $GOTOOLS_STRATEGY" >&2
            exit $E_ENVIRONMENT
            ;;
    esac

    # Resolve the actual installed version and update manifest.
    local resolved_ver="" pkg_base="${pkg%%@*}"
    case "$GOTOOLS_STRATEGY" in
        unified) resolved_ver=$(_resolve_installed_version "$GOTOOLS_DIR/go.mod" "$pkg_base") ;;
        split)   resolved_ver=$(_resolve_installed_version "$GOTOOLS_DIR/$modfile" "$pkg_base") ;;
        module)  resolved_ver=$(_resolve_installed_version "$GOTOOLS_DIR/$name/go.mod" "$pkg_base") ;;
    esac
    # Verify the binary was actually compiled and is runnable.
    # go get -tool may exit 0 even if compilation fails (the tool directive
    # is written to go.mod before the binary is built).  Run the tool with
    # /dev/null on stdin and check whether the go command itself can find the
    # binary.  A "go: "-prefixed error means the go tool couldn't find/resolve
    # the binary; any other output (or even a non-zero exit from the tool
    # itself) confirms the binary exists and is executable.
    local _verify_binary _verify_err
    case "$GOTOOLS_STRATEGY" in
        unified)
            _verify_binary=$(resolve_binary_name "$name" "$GOTOOLS_DIR/go.mod")
            _verify_err=$(cd "$GOTOOLS_DIR" && go tool "$_verify_binary" </dev/null 2>&1 >/dev/null) || true
            ;;
        split)
            _verify_binary=$(resolve_binary_name "$name" "$GOTOOLS_DIR/$modfile")
            _verify_err=$(cd "$GOTOOLS_DIR" && go tool -modfile="$modfile" "$_verify_binary" </dev/null 2>&1 >/dev/null) || true
            ;;
        module)
            _verify_binary=$(resolve_binary_name "$name" "$GOTOOLS_DIR/$name/go.mod")
            _verify_err=$(cd "$GOTOOLS_DIR/$name" && go tool "$_verify_binary" </dev/null 2>&1 >/dev/null) || true
            ;;
    esac
    if echo "$_verify_err" | grep -qiE '^(go: )?(no such tool|unknown command|tool not found)'; then
        echo "❌ Tool installed but not runnable: $name" >&2
        echo "   go tool error: $_verify_err" >&2
        exit $E_ENVIRONMENT
    fi

    # _INSTALL_NO_FLUSH=1: internal hook used by parallel sync — the parent
    # process merges the manifest after all jobs complete, so individual
    # background jobs must not write it (they would race and drop tools).
    if [[ "${_INSTALL_NO_FLUSH:-0}" != "1" ]]; then
        _manifest_tool_set "$name" "go" "$pkg_base" "${resolved_ver:-latest}"
        _manifest_flush
    fi

    echo "✅ Installed $name"

    # warn when @latest is used — floating versions break reproducibility.
    if [[ "$pkg" == *@latest ]]; then
        echo "⚠️  Installed at @latest (resolved: ${resolved_ver:-latest})."
        echo "   Pin this version for reproducibility:"
        echo "     gotools.sh install $name ${pkg_base}@${resolved_ver:-latest}"
    fi
}

# _list_json — output the tool list as a JSON object: schema_version,
# strategy/dir/go_version metadata, and a "tools" array of per-tool records.
# Single compact line; values escaped via _json_escape.

_list_json() {
    load_config
    printf '{"schema_version":1,"strategy":"%s","dir":"%s","go_version":"%s","tools":[' \
        "$(_json_escape "$GOTOOLS_STRATEGY")" "$(_json_escape "$GOTOOLS_DIR")" "$(_json_escape "$GOTOOLS_GO_VERSION")"
    local first=true _n _s _p _v
    while IFS='|' read -r _n _s _p _v; do
        [[ -z "$_n" ]] && continue
        local go_ver="?"
        case "$GOTOOLS_STRATEGY" in
            unified) go_ver=$(extract_go_version_from_mod "$GOTOOLS_DIR/go.mod" 2>/dev/null || echo "?") ;;
            split)   go_ver=$(extract_go_version_from_mod "$GOTOOLS_DIR/${_n}.mod" 2>/dev/null || echo "?") ;;
            module)  go_ver=$(extract_go_version_from_mod "$GOTOOLS_DIR/${_n}/go.mod" 2>/dev/null || echo "?") ;;
        esac
        $first && first=false || printf ','
        printf '{"name":"%s","source":"%s","package":"%s","version":"%s","go":"%s"}' \
            "$(_json_escape "$_n")" "$(_json_escape "$_s")" "$(_json_escape "$_p")" "$(_json_escape "$_v")" "$(_json_escape "$go_ver")"
    done <<< "$_MANIFEST_TOOLS"
    printf ']}\n'
}

# ---- list ----------------------------------------------------------------
cmd_list() {
    load_config
    _parse_output_format "$@"
    local arg
    for arg in "$@"; do
        case "$arg" in
            --json|--text|--format=json|--format=text) ;;
            *)
                echo "❌ Unknown argument: $arg" >&2
                echo "   Usage: $(basename "$0") list [--format=json|text]" >&2
                exit $E_USAGE
                ;;
        esac
    done

    if [[ "$_OUTPUT_FORMAT" == "json" ]]; then
        _list_json
        return
    fi

    printf "  %-18s %-6s %-10s %-8s %-30s %s\n" "TOOL" "SOURCE" "STRATEGY" "GO" "MODFILE" "PACKAGE@VERSION"
    printf "  %-18s %-6s %-10s %-8s %-30s %s\n" "----" "------" "--------" "--" "-------" "---------------"

    case "$GOTOOLS_STRATEGY" in
        unified)
            local modfile="$GOTOOLS_DIR/go.mod"
            if [[ -f "$modfile" ]]; then
                local go_ver rel_mod
                go_ver=$(extract_go_version_from_mod "$modfile")
                rel_mod=$(relative_path "$modfile")
                while IFS= read -r pkg; do
                    [[ -z "$pkg" ]] && continue
                    local name ver src
                    name=$(infer_binary_name_from_pkg "$pkg")
                    ver=$(extract_version_for_pkg "$modfile" "$pkg")
                    src=$(_manifest_tool_entry "$name" 2>/dev/null | cut -d'|' -f1)
                    printf "  %-18s %-6s %-10s %-8s %-30s %s\n" "$name" "${src:-go}" "unified" "${go_ver:-?}" "$rel_mod" "${pkg}@${ver:-unknown}"
                done < <(extract_tools_from_mod "$modfile")
            fi
            ;;

        split)
            for f in "$GOTOOLS_DIR"/*.mod; do
                [[ -f "$f" ]] || continue
                local name pkg ver go_ver rel_mod src
                name=$(basename "$f" .mod)
                pkg=$(extract_pkg_from_mod "$f")
                [[ -z "$pkg" ]] && continue
                ver=$(extract_version_for_pkg "$f" "$pkg")
                go_ver=$(extract_go_version_from_mod "$f")
                rel_mod=$(relative_path "$f")
                src=$(_manifest_tool_entry "$name" 2>/dev/null | cut -d'|' -f1)
                printf "  %-18s %-6s %-10s %-8s %-30s %s\n" "$name" "${src:-go}" "split" "${go_ver:-?}" "$rel_mod" "${pkg}@${ver:-unknown}"
            done
            ;;

        module)
            for d in "$GOTOOLS_DIR"/*/; do
                [[ -d "$d" ]] || continue
                local modfile="$d/go.mod"
                [[ -f "$modfile" ]] || continue
                local name pkg ver go_ver rel_mod src
                name=$(basename "$d")
                pkg=$(extract_pkg_from_mod "$modfile")
                [[ -z "$pkg" ]] && continue
                ver=$(extract_version_for_pkg "$modfile" "$pkg")
                go_ver=$(extract_go_version_from_mod "$modfile")
                rel_mod=$(relative_path "$modfile")
                src=$(_manifest_tool_entry "$name" 2>/dev/null | cut -d'|' -f1)
                printf "  %-18s %-6s %-10s %-8s %-30s %s\n" "$name" "${src:-go}" "module" "${go_ver:-?}" "$rel_mod" "${pkg}@${ver:-unknown}"
            done
            ;;

        *)
            echo "❌ Unknown strategy: $GOTOOLS_STRATEGY" >&2
            exit $E_ENVIRONMENT
            ;;
    esac

    # If nothing was printed from disk, show what's in the manifest.
    if [[ -z "$(extract_tools_with_versions 2>/dev/null)" ]]; then
        local _n _s _p _v
        while IFS='|' read -r _n _s _p _v; do
            [[ -z "$_n" ]] && continue
            printf "  %-18s %-6s %-10s %-8s %-30s %s\n" "$_n" "$_s" "$GOTOOLS_STRATEGY" "?" "(manifest)" "${_p}@${_v}"
        done <<< "$_MANIFEST_TOOLS"
    fi
}

# ---- migrate -------------------------------------------------------------



cmd_migrate() {
    _require_go
    _DRY_RUN=false
    for a in "$@"; do [[ "$a" == "--dry-run" ]] && _DRY_RUN=true; done
    if [[ $# -eq 0 ]]; then
        echo "❌ Usage: $(basename "$0") migrate <unified|split|module> [--dry-run]" >&2
        exit $E_USAGE
    fi

    local target_strategy="$1"

    case "$target_strategy" in
        unified|split|module) ;;
        *) echo "❌ Invalid strategy: $target_strategy (must be unified, split, or module)" >&2; exit $E_USAGE ;;
    esac

    load_config
    _acquire_lock

    # Use the on-disk structure as the source of truth for what we're
    # migrating *from*, not the config file (which may already be updated).
    local current_strategy
    current_strategy=$(detect_strategy "$GOTOOLS_DIR")
    current_strategy="${current_strategy:-$GOTOOLS_STRATEGY}"

    if [[ "$current_strategy" == "$target_strategy" ]]; then
        echo "ℹ️  Already using strategy '$target_strategy'. Nothing to do."
        return 0
    fi

    echo "🔀 Migrating from '$current_strategy' to '$target_strategy'..."

    # 1. Read the tools using the on-disk strategy, not the configured one.
    GOTOOLS_STRATEGY="$current_strategy"
    local tool_list
    tool_list=$(extract_tools_with_versions)

    if [[ -z "$tool_list" ]]; then
        echo "⚠️  No tools found to migrate."
    else
        echo "📋 Tools to migrate:"
        while IFS= read -r line; do
            echo "   $line"
        done <<< "$tool_list"
    fi

    if $_DRY_RUN; then
        echo "🔍 [dry-run] Would migrate $GOTOOLS_DIR/ from '$current_strategy' to '$target_strategy'."
        return
    fi

    # 2. Capture the Go version.
    local go_ver
    go_ver=$(resolve_go_version)

    # 3. Wipe old tools directory structure.
    echo "🧹 Cleaning old tools directory ($GOTOOLS_DIR)..."

    rm -rf "${GOTOOLS_DIR:?}"
    mkdir -p "$GOTOOLS_DIR"

    # 4. Update the manifest and force the live variable so that
    #    subsequent load_config / cmd_install calls in this process
    #    use the target strategy (not the old one).
    GOTOOLS_STRATEGY="$target_strategy"
    _manifest_flush
    _CONFIG_LOADED=true

    # 5. Re-initialize the new strategy structure.
    echo "🔧 Initializing new strategy ($target_strategy)..."

    case "$target_strategy" in
        unified)
            (cd "$GOTOOLS_DIR" && go mod init "$(tool_module_path)" && go mod edit -go="$go_ver")
            ;;
        split|module)
            ;;
    esac

    # 6. Re-install all tools at their exact pinned versions.
    # Clear the in-memory tool store so cmd_install doesn't refuse them as duplicates.
    _MANIFEST_TOOLS=""
    if [[ -n "$tool_list" ]]; then
        echo "📦 Re-installing tools under '$target_strategy' strategy..."
        while IFS=' ' read -r name pkg_at_version; do
            [[ -z "$name" ]] && continue
            echo "  → $name ($pkg_at_version)"
            cmd_install "$name" "$pkg_at_version"
        done <<< "$tool_list"
    fi

    echo "✅ Migration from '$current_strategy' to '$target_strategy' complete."
}
# ---- purge ---------------------------------------------------------------

# _purge_restore_hint — the init command that recreates this project's
# configuration. The tools themselves come back via the restore; the
# strategy/dir/go-version/prefix live only in the manifest and would
# otherwise be lost, so print how to reconstruct them.
_purge_restore_hint() {
    local cmd
    cmd="$(basename "$0") init --strategy=${GOTOOLS_STRATEGY}"
    [[ "${GOTOOLS_DIR:-}" != "tools" ]] && cmd+=" --dir=${GOTOOLS_DIR}"
    [[ -n "${GOTOOLS_GO_VERSION:-}" && "$GOTOOLS_GO_VERSION" != "inherit" ]] && cmd+=" --go=${GOTOOLS_GO_VERSION}"
    [[ -n "${GOTOOLS_MODULE_PREFIX:-}" ]] && cmd+=" --prefix=${GOTOOLS_MODULE_PREFIX}"
    echo "$cmd"
}

# _purge_restore_tools — the reverse of init's go.mod adoption: add every
# managed tool back to the root go.mod at its pinned version via
# `go get -tool`. Runs BEFORE the wipe so a failure leaves gotools intact.
_purge_restore_tools() {
    local root_mod="$_PROJECT_ROOT/go.mod"
    if [[ ! -f "$root_mod" ]]; then
        echo "❌ Cannot restore tools: no go.mod in project root." >&2
        exit $E_ENVIRONMENT
    fi

    local count=0
    local _n _s _p _v
    while IFS='|' read -r _n _s _p _v; do
        [[ -z "$_n" ]] && continue
        if [[ "$_s" != "go" ]]; then
            echo "  ⚠ $_n: source '$_s' — skipping (only go tools can be restored)"
            continue
        fi
        if $_DRY_RUN; then
            echo "  [dry-run] Would restore $_n (${_p}@${_v}) to go.mod"
            count=$((count + 1))
            continue
        fi
        echo "  ⬆ $_n (${_p}@${_v}) → go.mod"
        local _get_out
        if ! _get_out=$(go get -tool "${_p}@${_v}" 2>&1); then
            echo "❌ Failed to restore $_n" >&2
            echo "$_get_out" >&2
            if echo "$_get_out" | grep -qiE 'dial tcp|i/o timeout|connection timed out|no such host|connection refused|network is unreachable|could not resolve host|fetch failed|timeout exceeded'; then
                exit $E_NETWORK
            fi
            exit $E_GENERIC
        fi
        count=$((count + 1))
    done <<< "$_MANIFEST_TOOLS"

    if $_DRY_RUN; then
        echo "[dry-run] Would restore $count tool(s) to go.mod."
    elif [[ $count -gt 0 ]]; then
        echo "✅ Restored $count tool(s) to go.mod."
    else
        echo "ℹ No tools to restore."
    fi
}

cmd_purge() {
    _DRY_RUN=false
    local restore=false
    for a in "$@"; do
        case "$a" in
            --dry-run) _DRY_RUN=true ;;
            --restore) restore=true ;;
        esac
    done
    load_config
    _acquire_lock

    if $_DRY_RUN; then
        if $restore; then
            _purge_restore_tools
            echo "🔍 [dry-run] To come back: $(_purge_restore_hint)"
        fi
        echo "🔍 [dry-run] Would delete:"
        echo "  - $GOTOOLS_DIR/ (tools directory)"
        echo "  - $MANIFEST_FILE (manifest)"
        return
    fi

    echo "⚠️  WARNING: This will delete the tools directory ('$GOTOOLS_DIR') and '$MANIFEST_FILE'."
    if $restore; then
        echo "  It will also add the managed tools back to your go.mod."
    fi
    echo "This action cannot be undone."
    printf "Are you sure you want to proceed? (type YES to confirm): "
    read -r confirmation

    if [[ "$confirmation" != "YES" ]]; then
        echo "❌ Purge cancelled."
        return 0
    fi

    if $restore; then
        _purge_restore_tools
        echo "💡 To come back: $(_purge_restore_hint)"
    fi

    rm -rf "${GOTOOLS_DIR:?}" "${MANIFEST_FILE:?}"
    # Reset in-memory state.
    _MANIFEST_TOOLS=""
    echo "✅ Purge complete. All tools and configurations have been removed."
}

# ---- remove --------------------------------------------------------------



cmd_remove() {
    _require_go
    _DRY_RUN=false
    for a in "$@"; do [[ "$a" == "--dry-run" ]] && _DRY_RUN=true; done
    load_config
    _acquire_lock
    if [[ $# -eq 0 ]]; then
        echo "❌ Usage: $(basename "$0") remove <name1> [name2...] [--dry-run]" >&2
        exit $E_USAGE
    fi

    for name in "$@"; do
        [[ "$name" == "--dry-run" ]] && continue

        if $_DRY_RUN; then
            echo "  🔍 [dry-run] Would remove $name"
            continue
        fi
        echo "🗑️  Removing $name..."
        case "$GOTOOLS_STRATEGY" in
            unified)
                local modfile="$GOTOOLS_DIR/go.mod"
                if [[ -f "$modfile" ]]; then
                    local pkg
                    if pkg=$(pkg_for_tool "$name"); then
                        (cd "$GOTOOLS_DIR" && go mod edit -droptool="$pkg" && go mod tidy)
                        echo "  ✅ Dropped $name from $modfile"
                    else
                        echo "  ⚠️  Tool $name not found in $modfile"
                    fi
                fi
                ;;

            split)
                if [[ -f "$GOTOOLS_DIR/$name.mod" ]]; then
                    rm -f "$GOTOOLS_DIR/$name.mod" "$GOTOOLS_DIR/$name.sum"
                    echo "  ✅ Removed $name.mod / $name.sum"
                else
                    echo "  ⚠️  $name.mod not found."
                fi
                ;;

            module)
                if [[ -d "$GOTOOLS_DIR/$name" ]]; then
                    rm -rf "${GOTOOLS_DIR:?}/${name:?}"
                    echo "  ✅ Removed $GOTOOLS_DIR/$name/"
                else
                    echo "  ⚠️  $GOTOOLS_DIR/$name/ not found."
                fi
                ;;

            *)
                echo "❌ Unknown strategy: $GOTOOLS_STRATEGY" >&2
                exit $E_ENVIRONMENT
                ;;
        esac

        # Remove from manifest.
        _manifest_tool_remove "$name"
    done

    _manifest_flush
}
# ---- self-update ---------------------------------------------------------

# _self_update_verify_checksum <file> <expected> — refuse to install a
# self-update whose SHA-256 does not match the release manifest. On
# mismatch the downloaded file is deleted before exiting.
_self_update_verify_checksum() {
    local file="$1" expected_checksum="$2"
    local actual
    if ! actual=$(_sha256 "$file"); then
        echo "❌ Error: Neither sha256sum nor shasum is available." >&2
        rm -f "$file"
        exit $E_GENERIC
    fi
    if [[ "$actual" != "$expected_checksum" ]]; then
        echo "❌ Checksum verification FAILED." >&2
        echo "   Expected: $expected_checksum" >&2
        echo "   Got:      $actual" >&2
        echo "   The downloaded file has been tampered with." >&2
        rm -f "$file"
        echo "   The file has been deleted. Report this at:" >&2
        echo "   https://github.com/$REPO/issues" >&2
        exit $E_GENERIC
    fi
    echo "  🔐 Checksum verified: ${expected_checksum:0:16}..."
}

cmd_self_update() {
    echo "🔍 Checking for updates..."
    local latest_tag
    latest_tag=$(curl -sL "$API_URL" | grep '"tag_name":' | sed -E 's/.*"([^"]+)".*/\1/') || true

    if [[ -z "$latest_tag" ]]; then
        echo "❌ Error: Could not fetch latest version from GitHub." >&2
        return $E_NETWORK
    fi

    if [[ "$latest_tag" == "$VERSION" ]]; then
        echo "✅ You are already on the latest version ($VERSION)."
        return 0
    fi

    echo "🚀 New version found: $latest_tag (Current: $VERSION)"

    # If $0 doesn't end in .sh, we're running inside the Go binary wrapper.
    # We can't overwrite a compiled binary with a shell script — use go install.
    if [[ "$0" != *.sh ]]; then
        echo "📥 Updating via go install..."
        go install "github.com/piusalfred/gotools/cmd/gotools@$latest_tag" || {
            echo "❌ Error: go install failed." >&2
            return $E_GENERIC
        }
        echo "  🔐 Integrity verified by the Go module checksum database."
        echo "✨ Successfully updated to $latest_tag!"
        return 0
    fi

    echo "📥 Downloading update..."

    # 1. Fetch the release checksum manifest.
    local checksum_file
    checksum_file=$(mktemp)
    local checksum_url="https://github.com/$REPO/releases/download/$latest_tag/checksums-sha256.txt"
    if ! curl -sSL --fail --connect-timeout 10 "$checksum_url" -o "$checksum_file"; then
        echo "❌ Error: Failed to download checksums file." >&2
        rm -f "$checksum_file"
        return $E_NETWORK
    fi

    # 2. Extract the expected SHA-256 for gotools.sh.
    local expected_checksum
    expected_checksum=$(grep 'gotools\.sh' "$checksum_file" | awk '{print $1}' | head -n1)
    if [[ -z "$expected_checksum" ]]; then
        echo "❌ Error: Could not find checksum for gotools.sh" >&2
        rm -f "$checksum_file"
        return $E_GENERIC
    fi

    # 3. Download the script and verify it before touching $0.
    local tmp_file
    tmp_file=$(mktemp)
    local tag_url="https://raw.githubusercontent.com/$REPO/$latest_tag/gotools.sh"

    if ! curl -sSL --fail --connect-timeout 30 "$tag_url" -o "$tmp_file"; then
        echo "❌ Error: Update download failed." >&2
        rm -f "$tmp_file" "$checksum_file"
        return $E_NETWORK
    fi

    _self_update_verify_checksum "$tmp_file" "$expected_checksum"

    mv "$tmp_file" "$0"
    chmod +x "$0"
    rm -f "$checksum_file"
    echo "✨ Successfully updated to $latest_tag!"
}
# ---- sync ----------------------------------------------------------------

# _sync_fingerprint <go-version> — a deterministic fingerprint of the state
# sync reconciles: the full tool list (names, packages, AND versions), the
# strategy, the resolved Go version, and the module prefix. Any manifest or
# environment change produces a different fingerprint.
_sync_fingerprint() {
    local go_ver="$1"
    local fp
    # Sort the tool list before hashing: the in-memory order depends on how
    # the manifest was built (parsed vs appended), but the fingerprint must
    # not. Same ordering as _manifest_flush.
    fp=$(printf '%s' "$_MANIFEST_TOOLS" | LC_ALL=C sort -t'|' -k2,2 -k3,3 -k4,4 -k1,1 | _sha256 /dev/stdin)
    fp="${fp}|${GOTOOLS_STRATEGY}|${go_ver}|$(resolve_module_prefix)"
    printf '%s' "$fp"
}

# _sync_write_fingerprint <go-version> — record the reconciled state so the
# next sync can take the fast path. Written only after a successful sync.
_sync_write_fingerprint() {
    printf '%s\n' "$(_sync_fingerprint "$1")" > "$GOTOOLS_DIR/.gotools.fingerprint"
}

# _sync_install_one <name> <pkg@version> — one backgroundable reinstall unit.
# _INSTALL_NO_FLUSH=1 makes cmd_install skip the manifest write: parallel
# jobs each run in their own subshell, so letting them flush would race and
# drop tools (last writer wins). The parent merges and flushes once.
_sync_install_one() {
    local name="$1" pkg_at_version="$2"
    _INSTALL_NO_FLUSH=1 cmd_install --force "$name" "$pkg_at_version"
}

# _sync_run_reinstalls_serial <list> — sequential reinstalls (unified
# strategy and --jobs 1).
_sync_run_reinstalls_serial() {
    local _n pkg_at_version
    while IFS='|' read -r _n pkg_at_version; do
        [[ -z "$_n" ]] && continue
        # --force: the tool is already in the manifest — restoring a missing
        # or drifted modfile must not trip cmd_install's duplicate check.
        cmd_install --force "$_n" "$pkg_at_version"
    done <<< "$1"
}

# _sync_run_reinstalls_parallel <jobs> <list> — concurrent reinstalls for
# split/module strategies (independent modfiles). After all jobs complete,
# the parent merges every reinstalled tool into the manifest and flushes
# once, so concurrent jobs never race on the manifest.
_sync_run_reinstalls_parallel() {
    local jobs="$1" list="$2"
    # Separate declaration/assignment for bash 3.2 compatibility.
    local -a spec
    spec=()
    local _n pkg_at_version
    while IFS='|' read -r _n pkg_at_version; do
        [[ -z "$_n" ]] && continue
        spec+=("$_n" "$pkg_at_version" "::")
    done <<< "$list"
    _parallel_for "$jobs" _sync_install_one ${spec[@]+"${spec[@]}"}

    local _name _pkg_ver pkg resolved
    while IFS='|' read -r _name _pkg_ver; do
        [[ -z "$_name" ]] && continue
        pkg="${_pkg_ver%%@*}"
        resolved=$(_tool_disk_version "$_name" "$pkg")
        _manifest_tool_set "$_name" "go" "$pkg" "${resolved:-latest}"
    done <<< "$list"
    _manifest_flush
}

# _tool_disk_version <name> <pkg> — the version currently on disk for a tool,
# per strategy. Callers must ensure the modfile exists first.
_tool_disk_version() {
    local name="$1" pkg="$2"
    case "$GOTOOLS_STRATEGY" in
        unified) extract_version_for_pkg "$GOTOOLS_DIR/go.mod" "$pkg" ;;
        split)   extract_version_for_pkg "$GOTOOLS_DIR/${name}.mod" "$pkg" ;;
        module)  extract_version_for_pkg "$GOTOOLS_DIR/${name}/go.mod" "$pkg" ;;
    esac
}

_tool_version_matches() {
    local name="$1" pkg="$2" expected="$3"
    local disk
    disk=$(_tool_disk_version "$name" "$pkg")
    [[ -n "$disk" && "$disk" == "$expected" ]]
}

# _sync_fast_path <go-version> [message] — skip the full reconciliation when
# nothing changed. The fingerprint must match AND (defense in depth) every
# modfile must exist with the manifest version — catches manual edits that
# bypassed the manifest. Returns 0 and prints the success message on a hit.
_sync_fast_path() {
    local go_ver="$1"
    local success_message="${2:-✅ Tools up to date.}"
    local fingerprint_file="$GOTOOLS_DIR/.gotools.fingerprint"
    local current_fp
    current_fp=$(_sync_fingerprint "$go_ver")
    if [[ -f "$fingerprint_file" ]] && [[ "$(cat "$fingerprint_file")" == "$current_fp" ]]; then
        local all_ok=true
        local _n _s _p _v
        while IFS='|' read -r _n _s _p _v; do
            [[ -z "$_n" ]] && continue
            case "$GOTOOLS_STRATEGY" in
                unified) [[ -f "$GOTOOLS_DIR/go.mod" ]] || { all_ok=false; break; } ;;
                split)   [[ -f "$GOTOOLS_DIR/${_n}.mod" ]] || { all_ok=false; break; } ;;
                module)  [[ -f "$GOTOOLS_DIR/${_n}/go.mod" ]] || { all_ok=false; break; } ;;
            esac
            _tool_version_matches "$_n" "$_p" "$_v" || { all_ok=false; break; }
        done <<< "$_MANIFEST_TOOLS"
        if $all_ok; then
            echo "$success_message"
            return 0
        fi
    fi
    return 1
}

cmd_sync() {
    _require_go
    _DRY_RUN=false
    _parse_offline "$@"
    # Parallelism is opt-in: sync stays serial unless --jobs N (or
    # GOTOOLS_JOBS) explicitly requests more than one concurrent install.
    local jobs="${GOTOOLS_JOBS:-1}"
    local jobs_explicit=false
    while [[ $# -gt 0 ]]; do
        case "$1" in
            --dry-run) _DRY_RUN=true ;;
            --jobs=*) jobs="${1#*=}"; jobs_explicit=true ;;
            --jobs) jobs="${2:-4}"; jobs_explicit=true; shift ;;
        esac
        shift
    done
    if ! [[ "$jobs" =~ ^[0-9]+$ ]]; then
        echo "❌ Invalid --jobs value: must be a positive number" >&2
        exit $E_USAGE
    fi

    load_config
    _acquire_lock
    local target_v
    target_v=$(resolve_go_version)

    # Offline mode: hermetic CI runs take ONLY the fingerprint fast path.
    # Anything that would need the network refuses with exit 6 instead of
    # making the build depend on proxy conditions. Also covers a strategy
    # mismatch (migrating needs the network).
    if ${_OFFLINE:-false}; then
        if _sync_fast_path "$target_v" "✅ Tools up to date (fingerprint match)."; then
            return 0
        fi
        echo "❌ Offline mode: manifest has changed. Network required." >&2
        echo "   Run 'gotools sync' locally and commit the updated files." >&2
        exit $E_OFFLINE
    fi

    local disk_strategy
    disk_strategy=$(detect_strategy "$GOTOOLS_DIR")

    if [[ -n "$disk_strategy" && "$disk_strategy" != "$GOTOOLS_STRATEGY" ]]; then
        if $_DRY_RUN; then
            echo "🔍 [dry-run] Would auto-migrate from '$disk_strategy' to '$GOTOOLS_STRATEGY'"
            return
        fi
        echo "⚠️  Strategy mismatch: $MANIFEST_FILE says '$GOTOOLS_STRATEGY' but $GOTOOLS_DIR/ looks like '$disk_strategy'."
        echo "🔀 Auto-migrating to '$GOTOOLS_STRATEGY'..."
        cmd_migrate "$GOTOOLS_STRATEGY"
        return
    fi

    # Fast path: when the fingerprint matches and every modfile still carries
    # the manifest version, there is nothing to reconcile.
    if ! $_DRY_RUN && _sync_fast_path "$target_v"; then
        return 0
    fi

    if $_DRY_RUN; then
        echo "🔍 [dry-run] Would sync (strategy=$GOTOOLS_STRATEGY, go=$target_v, dir=$GOTOOLS_DIR)"
    else
        echo "🔄 Syncing (strategy=$GOTOOLS_STRATEGY, go=$target_v, dir=$GOTOOLS_DIR)..."
    fi

    # ---- Existing Go sync logic (tidy existing modfiles) ----
    case "$GOTOOLS_STRATEGY" in
        unified)
            if $_DRY_RUN; then
                echo "  [dry-run] Would go mod tidy in $GOTOOLS_DIR/"
            else
                mkdir -p "$GOTOOLS_DIR"
                if [[ ! -f "$GOTOOLS_DIR/go.mod" ]]; then
                    (cd "$GOTOOLS_DIR" && go mod init "$(tool_module_path)")
                fi
                (cd "$GOTOOLS_DIR" && go mod edit -go="$target_v" && go mod tidy)
            fi
            ;;

        split)
            if $_DRY_RUN; then
                for f in "$GOTOOLS_DIR"/*.mod; do
                    [[ -f "$f" ]] || continue
                    echo "  [dry-run] Would tidy $(basename "$f")"
                done
            else
                mkdir -p "$GOTOOLS_DIR"
                local parent_mod
                parent_mod=$(resolve_module_prefix)
                for f in "$GOTOOLS_DIR"/*.mod; do
                    [[ -f "$f" ]] || continue
                    local base sumfile
                    base=$(basename "$f")
                    sumfile="${f%.mod}.sum"
                    echo "  ↻ $base"
                    # Isolate: copy to a temp dir so Go doesn't discover the
                    # parent module (go mod tidy -modfile cannot reconcile two
                    # module identities when run from inside another module's tree).
                    # Also add a replace directive so Go uses the local parent
                    # module (which has all packages) instead of the stale
                    # published version which may be missing packages.
                    local tmpdir
                    tmpdir=$(mktemp -d)
                    cp "$f" "$tmpdir/go.mod"
                    [[ -f "$sumfile" ]] && cp "$sumfile" "$tmpdir/go.sum"
                    if [[ -n "$parent_mod" ]]; then
                        (cd "$tmpdir" && go mod edit -replace="${parent_mod}=${PWD}" && go mod edit -go="$target_v" && go mod tidy && go mod edit -dropreplace="$parent_mod")
                    else
                        (cd "$tmpdir" && go mod edit -go="$target_v" && go mod tidy)
                    fi
                    cp "$tmpdir/go.mod" "$f"
                    cp "$tmpdir/go.sum" "$sumfile"
                    rm -rf "$tmpdir"
                done
            fi
            ;;

        module)
            if $_DRY_RUN; then
                for d in "$GOTOOLS_DIR"/*/; do
                    [[ -d "$d" ]] || continue
                    [[ -f "$d/go.mod" ]] || continue
                    echo "  [dry-run] Would tidy $(basename "$d")"
                done
            else
                mkdir -p "$GOTOOLS_DIR"
                for d in "$GOTOOLS_DIR"/*/; do
                    [[ -d "$d" ]] || continue
                    local modfile="$d/go.mod"
                    [[ -f "$modfile" ]] || continue
                    local name
                    name=$(basename "$d")
                    echo "  ↻ $name"
                    (cd "$d" && go mod edit -go="$target_v" && go mod tidy)
                done
            fi
            ;;

        *)
            echo "❌ Unknown strategy: $GOTOOLS_STRATEGY" >&2
            exit $E_ENVIRONMENT
            ;;
    esac

    # ---- Discover tools on disk not yet in the manifest ----
    local discovered=0
    local tool_line
    while IFS= read -r tool_line; do
        [[ -z "$tool_line" ]] && continue
        local disk_name disk_pkg
        disk_name=$(echo "$tool_line" | awk '{print $1}')
        disk_pkg=$(echo "$tool_line" | awk '{print $2}')
        if ! _manifest_tool_exists "$disk_name"; then
            local disk_ver
            disk_ver=$(echo "$disk_pkg" | sed 's/.*@//')
            local disk_pkg_base="${disk_pkg%%@*}"
            _manifest_tool_set "$disk_name" "go" "$disk_pkg_base" "$disk_ver"
            echo "  ✚ $disk_name ($disk_pkg) — discovered from disk"
            discovered=$((discovered + 1))
        fi
    done <<< "$(extract_tools_with_versions)"
    if [[ $discovered -gt 0 ]]; then
        _manifest_flush
        echo "✅ Added $discovered tool(s) to manifest."
    fi

    # ---- Reinstall tools from the manifest that are missing or drifted ----
    # First collect the work (one "name|pkg@version" line per reinstall),
    # then run it serial or parallel depending on strategy and --jobs.
    local reinstall_list=""
    local _n _s _p _v
    while IFS='|' read -r _n _s _p _v; do
        [[ -z "$_n" ]] && continue
        local on_disk=false disk_ver=""
        case "$GOTOOLS_STRATEGY" in
            unified) [[ -f "$GOTOOLS_DIR/go.mod" ]] && on_disk=true ;;
            split)   [[ -f "$GOTOOLS_DIR/${_n}.mod" ]] && on_disk=true ;;
            module)  [[ -f "$GOTOOLS_DIR/${_n}/go.mod" ]] && on_disk=true ;;
        esac
        if $on_disk; then
            disk_ver=$(_tool_disk_version "$_n" "$_p")
        fi
        if ! $on_disk || [[ "$disk_ver" != "$_v" ]]; then
            if $_DRY_RUN; then
                echo "  🔍 [dry-run] Would reinstall $_n ($_p@$_v)"
            elif ! $on_disk; then
                echo "  ⬇ $_n ($_p@$_v) — missing, reinstalling..."
            else
                echo "  ⚠ $_n: manifest $_v, disk ${disk_ver:-unknown} — reinstalling..."
            fi
            reinstall_list+="${_n}|${_p}@${_v}"$'\n'
        fi
    done <<< "$_MANIFEST_TOOLS"

    local missing_count
    missing_count=$(printf '%s' "$reinstall_list" | grep -c . || true)

    if ! $_DRY_RUN && [[ -n "$reinstall_list" ]]; then
        if [[ "$GOTOOLS_STRATEGY" == "unified" ]]; then
            if $jobs_explicit && [[ "$jobs" -gt 1 ]]; then
                echo "  ⚠ unified strategy: installs are serial (shared go.mod)."
            fi
            _sync_run_reinstalls_serial "$reinstall_list"
        elif [[ "$jobs" -le 1 ]]; then
            _sync_run_reinstalls_serial "$reinstall_list"
        else
            _sync_run_reinstalls_parallel "$jobs" "$reinstall_list"
        fi
    fi

    if $_DRY_RUN; then
        echo "🔍 [dry-run] Would restore $missing_count tool(s) from manifest."
    else
        # Record the state we just reconciled so the next sync can skip
        # straight to the fast path.
        _sync_write_fingerprint "$target_v"
        if [[ $missing_count -gt 0 ]]; then
            echo "✅ Sync restored $missing_count tool(s) from manifest."
        else
            echo "✅ Sync complete."
        fi
    fi
}

# ---- test (signal / cancellation helper) ---------------------------------



cmd_test() {
    if [[ $# -eq 0 ]]; then
        echo "❌ Usage: $(basename "$0") test <seconds>" >&2
        exit $E_USAGE
    fi

    local seconds="$1"

    # Validate that the argument is a positive number.
    if ! [[ "$seconds" =~ ^[0-9]+(\.[0-9]+)?$ ]] || [[ "$seconds" == "0" ]]; then
        echo "❌ Error: <seconds> must be a positive number, got '$seconds'" >&2
        exit $E_USAGE
    fi

    # Trap SIGINT and SIGTERM so we can report the signal before exiting.
    trap 'echo ""; echo "⚡ Caught SIGINT (Ctrl-C) — exiting."; exit 130' INT
    trap 'echo ""; echo "⚡ Caught SIGTERM — exiting."; exit 143' TERM

    echo "⏳ Sleeping for ${seconds}s — press Ctrl-C to test signal handling..."

    local elapsed=0
    while (( $(echo "$elapsed < $seconds" | bc -l) )); do
        sleep 1 &
        wait $! 2>/dev/null || true  # wait on bg sleep so traps fire immediately
        elapsed=$(echo "$elapsed + 1" | bc -l)
        printf "\r  ⏱  %g / %s seconds" "$elapsed" "$seconds"
    done

    echo ""
    echo "✅ Finished — no interruption."
}

# ---- uninstall -----------------------------------------------------------



cmd_uninstall() {
    echo "⚠️  WARNING: This will delete the 'gotools.sh' script itself."
    printf "Do you want to uninstall gotools.sh? (y/N): "
    read -r confirmation

    if [[ "$confirmation" =~ ^[Yy]$ ]]; then
        local script_path
        script_path="$(cd "$(dirname "$0")" && pwd)/$(basename "$0")"
        rm -f "$script_path"
        echo "✅ gotools.sh has been uninstalled. Goodbye!"
        exit 0
    else
        echo "❌ Uninstall cancelled."
    fi
}

# ---- upgrade -------------------------------------------------------------



cmd_upgrade() {
    _require_go
    _DRY_RUN=false
    # Filter flags out so they never leak into the target list.
    local filtered=()
    for a in "$@"; do
        case "$a" in
            --dry-run) _DRY_RUN=true ;;
            --offline) _OFFLINE=true ;;
            *) filtered+=("$a") ;;
        esac
    done
    _parse_offline "$@"
    set -- ${filtered[@]+"${filtered[@]}"}

    load_config
    _acquire_lock
    if [[ $# -eq 0 ]]; then
        echo "❌ Usage: $(basename "$0") upgrade <name|all> [--dry-run]" >&2
        exit $E_USAGE
    fi

    # Upgrading resolves @latest from the proxy — refuse in offline mode.
    if ${_OFFLINE:-false}; then
        echo "❌ Offline mode: cannot upgrade tools without network." >&2
        exit $E_OFFLINE
    fi

    local targets=()

    if [[ "$1" == "all" ]]; then
        # Use manifest for target collection — single code path for all strategies.
        # Use tool names (not package paths) for unified strategy collection.
        while IFS='|' read -r name _ _ _; do
            [[ -n "$name" ]] && targets+=("$name")
        done <<< "$_MANIFEST_TOOLS"
    else
        targets=("$@")
    fi

    if [[ ${#targets[@]} -eq 0 ]]; then
        echo "⚠️  No tools found to upgrade."
        return 0
    fi

    for t in "${targets[@]}"; do
        local entry pkg ver
        entry=$(_manifest_tool_entry "$t" 2>/dev/null || true)
        if [[ -z "$entry" ]]; then
            echo "  ⚠️  Tool $t not found in manifest, skipping."
            continue
        fi
        pkg=$(echo "$entry" | cut -d'|' -f2)
        local old_ver
        old_ver=$(echo "$entry" | cut -d'|' -f3)

        if $_DRY_RUN; then
            echo "  🔍 [dry-run] Would upgrade $t ($pkg) to @latest"
            continue
        fi
        echo "🚀 Upgrading $t ($pkg) from ${old_ver:-?}..."
        case "$GOTOOLS_STRATEGY" in
            unified)
                (cd "$GOTOOLS_DIR" && go get -tool "${pkg}@latest")
                ;;
            split)
                (cd "$GOTOOLS_DIR" && go get -tool -modfile="$t.mod" "${pkg}@latest")
                ;;
            module)
                (cd "$GOTOOLS_DIR/$t" && go get -tool "${pkg}@latest")
                ;;
        esac

        # Update version in manifest after upgrade.
        local new_ver=""
        case "$GOTOOLS_STRATEGY" in
            unified) new_ver=$(_resolve_installed_version "$GOTOOLS_DIR/go.mod" "$pkg") ;;
            split)   new_ver=$(_resolve_installed_version "$GOTOOLS_DIR/$t.mod" "$pkg") ;;
            module)  new_ver=$(_resolve_installed_version "$GOTOOLS_DIR/$t/go.mod" "$pkg") ;;
        esac
        if [[ -n "$new_ver" ]]; then
            _manifest_tool_set "$t" "go" "$pkg" "$new_ver"
            if [[ "$new_ver" != "$old_ver" ]]; then
                echo "  ✅ $t: ${old_ver:-?} → $new_ver"
            else
                echo "  ✅ $t: already at latest ($new_ver)"
            fi
        else
            echo "  ⚠️  $t: could not resolve new version"
        fi
    done

    if $_DRY_RUN; then
        echo "🔍 [dry-run] Would upgrade ${#targets[@]} tool(s)."
    else
        _manifest_flush
        echo "✅ Upgrade complete."
    fi
}

# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------




cmd_version() {
    _parse_output_format "$@"
    local arg
    for arg in "$@"; do
        case "$arg" in
            --json|--text|--format=json|--format=text) ;;
            *)
                echo "❌ Unknown argument: $arg" >&2
                echo "   Usage: $(basename "$0") version [--format=json|text]" >&2
                exit $E_USAGE
                ;;
        esac
    done

    if [[ "$_OUTPUT_FORMAT" == "json" ]]; then
        printf '{"schema_version":1,"name":"gotools.sh","version":"%s"}\n' "$(_json_escape "$VERSION")"
    else
        echo "gotools.sh $VERSION"
    fi
}

# _stdin_install — read "go install <tool>" lines from stdin and install each.
# Strips the "go install " prefix, trims whitespace, and delegates to
# cmd_install for each non-empty line. Lines without the prefix are passed
# through as-is, so bare "pkg@version" also works.



_stdin_install() {
    local line count=0
    while IFS= read -r line || [[ -n "$line" ]]; do
        # Trim leading / trailing whitespace
        line="${line#"${line%%[![:space:]]*}"}"
        line="${line%"${line##*[![:space:]]}"}"
        [[ -z "$line" ]] && continue

        # Strip "go install " prefix if present
        if [[ "$line" == "go install "* ]]; then
            line="${line#go install }"
        fi

        # Trim again after stripping the prefix
        line="${line#"${line%%[![:space:]]*}"}"
        [[ -z "$line" ]] && continue

        # shellcheck disable=SC2086
        cmd_install $line
        count=$((count + 1))
    done </dev/stdin
    if [[ $count -eq 0 ]]; then
        echo "❌ No tool specifications found on stdin." >&2
        echo "   Pipe one or more lines such as: go install <package>@<version>" >&2
        exit $E_USAGE
    fi
}

# ---------------------------------------------------------------------------
# Main dispatch — only runs when executed as a script, not when sourced.
# Uses the standard `return 2>/dev/null` trick: return succeeds only inside
# a sourced script (or function), fails at the top level of an executed script.
# This correctly handles direct execution, `bash -c` (Go wrapper), and source.
# ---------------------------------------------------------------------------
if ! (return 0 2>/dev/null); then
    if [[ $# -lt 1 ]]; then
        # When stdin is not a terminal AND has data waiting, read
        # "go install <tool>" lines from it.  Otherwise show usage.
        if [[ ! -t 0 ]]; then
            _first_byte=""
            _first_byte=$(dd bs=1 count=1 2>/dev/null)
            if [[ -n "$_first_byte" ]]; then
                {
                    printf '%s' "$_first_byte"
                    cat
                } | _stdin_install
                exit ${PIPESTATUS[0]}
            fi
        fi
        usage
    fi
    action="$1"
    shift

    # If the first argument after the command is --help or -h,
    # show per-command help instead of dispatching normally.
    if [[ "${1:-}" == "--help" || "${1:-}" == "-h" ]]; then
        _cmd_help "$action"
        exit 0
    fi

    case "$action" in
        init)                     cmd_init "$@" ;;
        install)                  cmd_install "$@" ;;
        sync)                     cmd_sync "$@" ;;
        exec)                     cmd_exec "$@" ;;
        list)                     cmd_list "$@" ;;
        upgrade|update)           cmd_upgrade "$@" ;;
        remove)                   cmd_remove "$@" ;;
        info)                     cmd_info "$@" ;;
        migrate)                  cmd_migrate "$@" ;;
        config)                   cmd_config "$@" ;;
        purge)                    cmd_purge "$@" ;;
        check)                    cmd_check ;;
        doctor)                   cmd_doctor "$@" ;;
        completion)               cmd_completion "$@" ;;
        version)                  cmd_version "$@" ;;
        self-update|self-upgrade) cmd_self_update ;;
        uninstall)                cmd_uninstall ;;
        test)                     cmd_test "$@" ;;
        help|--help|-h)           usage ;;
        *)                        echo "❌ Unknown command: $action" >&2; usage ;;
    esac
fi
